TN.defSec("neurology",{"headache-high-risk-workup":{"id":"headache-high-risk-workup","variants":[{"id":"headache-high-risk-main","o":{"I":[{"t":"Noncontrast CT head STAT (ICH, SAH, SDH, mass, signs of raised ICP; most sensitive early — 98% within 6–12 h)"},{"t":"If CT negative and suspicion remains: CT angiography or lumbar puncture (RBCs, xanthochromia); MRI / MR venography for cerebral venous thrombosis; MRA / CTA for dissection or small SAH"}],"L":[{"t":"Glucose (bedside); CBC, PT/INR, aPTT, electrolytes, creatinine; ESR / CRP if age > 50; pregnancy test; troponin / ECG (SAH-related changes); toxicology if indicated"}],"S":[{"t":"Analgesia (avoid anticoagulants / antiplatelets); antiemetic as needed"}],"T":[{"t":"Neurological monitoring; BP control only if SAH confirmed (see stroke / SAH)"}],"Co":[{"t":"Neurosurgery / neurology if positive; admit for diagnostic workup if undiagnosed high-risk"}]},"name":"Thunderclap / red-flag headache — SAH and mimics workup","level":"I","imp":"Headache with red-flag features, rule out SAH / intracranial pathology","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"زن ۴۵ ساله با سردرد ناگهانی و شدیدترین سردرد عمر، استفراغ و گردن‌درد.","why":"CT بدون کنتراست بلافاصله؛ منفی: CTA یا LP."}],"ch":"140","name":"Headache with high-risk features / thunderclap headache (screening and workup)","name_fa":"سردرد با ویژگی‌های پرخطر / سردرد ناگهانی شدید (thunderclap)","cc":["headache"],"keywords":"thunderclap headache, red flags headache, subarachnoid hemorrhage, cerebral venous thrombosis, RCVS, pituitary apoplexy, dissection, brain tumor, سردرد ناگهانی, علائم خطر سردرد","status":"draft","features":["اغلب خوش‌خیم (96%)؛ جدول 140-1 «red flags»: شروع: ناگهانی، تروما، فعالیت؛ علائم: تغییر هوشیاری، تشنج، تب، علائم عصبی، تغییر بینایی؛ دارو: ضدانعقاد/آنتی‌پلاکت، آنتی‌بیوتیک اخیر، سرکوب ایمنی؛ سابقه: بدون سردرد قبلی، تغییر کیفیت یا بدتر شدن پیشرونده طی هفته/ماه؛ بیماری همراه: بارداری/پس از زایمان، SLE، Behçet، واسکولیت، سارکوئیدوز، سرطان؛ معاینه: تغییر هوشیاری، تب، سفتی گردن، پاپیلادم، علائم کانونی","سن > 50 با سردرد جدید یا بدتر شونده؛ thunderclap (حداکثر شدت ناگهانی): 10 تا 14% علت پرخطر؛ جدول 140-2 علل: خونریزی (داخل‌جمجمه‌ای، «sentinel»، ICH خودبه‌خودی)، عروقی (دیسکسیون کاروتید/vertebrobasilar، RCVS، ترومبوز سینوس وریدی، PRES)، سایر (coital، Valsalva، افت فشار داخل‌جمجمه خودبه‌خودی، هیدروسفالی حاد (colloid cyst)، apoplexy هیپوفیز)","تومور مغز: دوطرفه یا یک‌طرفه، ثابت یا متناوب؛ بدتر هنگام بیدار شدن، با Valsalva، وضعیتی و با تهوع/استفراغ؛ در بیمار سرطانی، تشنج یا تغییر هوشیاری","ترومبوز سینوس وریدی (CVT): OCP، پس از زایمان/جراحی، کمبود فاکتور انعقادی، پلی‌سیتمی؛ پاپیلادم، علائم عصبی نوسانی؛ LP: فشار باز بالا؛ MR venography تشخیصی؛ هماتوم ساب‌دورال/ICH: سالمند، الکلی، سوءمصرف، مصرف ضدانعقاد؛ خونریزی مخچه با علائم وستیبولار ← مشاوره جراحی","ارزیابی: کیفیت، الگو، فراوانی، شدت، محل و علائم همراه؛ آزمایش اغلب محدود؛ ESR/CRP در شک آرتریت temporal؛ CT بدون کنتراست: ICH، SDH، توده، ICP بالا، SAH؛ منفی با شک بالا: ادامه (LP، CTA)؛ MRI/MRV (CVT)، MRA/CTA (دیسکسیون، SAH کوچک)؛ LP: منژیت/انسفالیت یا SAH پس از CT منفی"],"ddx":[{"n":"Subarachnoid hemorrhage |","cm":1},{"n":"Meningitis / encephalitis |","cm":1},{"n":"Intracranial hemorrhage / SDH / mass lesion |","cm":1},{"n":"Cerebral venous thrombosis / dissection / RCVS / PRES |"},{"n":"Pituitary apoplexy / acute hydrocephalus |"}],"redflags":["سردرد ناگهانی، تب و سفتی گردن، پاپیلادم، علائم کانونی، تغییر هوشیاری، سن > 50، ضدانعقاد"],"guide":"ارزیابی اولیه با شرح حال و معاینه؛ در صورت اندیکاسیون تست و تصویربرداری بر اساس عوامل خطر؛ درمان اختصاصی بیماری و مشاوره تخصصی. مشاوره بر اساس علت مشکوک، کنترل ناکافی علائم در ED یا نیاز به بستری. هنگام ترخیص: دستور بازگشت (بدتر شدن، عدم بهبود، علائم جدید: تب، سفتی گردن، تغییر بینایی، علائم عصبی)، عوارض دارو و پیگیری.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 140: Headache, pp. 759–764"},"migraine-headache":{"id":"migraine-headache","variants":[{"id":"migraine-main","o":{"L":[{"t":"(no routine labs; pregnancy test if childbearing age before DHE / ketorolac)"}],"S":[{"t":"Normal saline bolus (pretreat before chlorpromazine to minimize hypotension)","fl":[{"k":"ci","v":"caution in heart failure"}]},{"t":"Metoclopramide 10 mg IV, or prochlorperazine 5–10 mg IV, or chlorpromazine 7.5 mg IV, or droperidol 2.5 mg IV slow (concurrent diphenhydramine for dystonic reaction prevention)","fl":[{"k":"hi","v":""}]},{"t":"Ketorolac 30 mg IV or IM","fl":[{"k":"ci","v":"peptic ulcer disease, renal disease, pregnancy 3rd trimester"}]},{"t":"Dexamethasone 6–10 mg IV (adjunct to reduce recurrence)"},{"t":"Sumatriptan 6 mg SC, or DHE 1 mg IV over 3 min (with antiemetic pretreat)","fl":[{"k":"ci","v":"ischemic heart disease, uncontrolled hypertension, basilar / hemiplegic migraine, pregnancy; no DHE within 24 h of sumatriptan"}]},{"t":"Rescue: magnesium sulfate 2 g IV over 30 min, valproate 500 mg IV, methylprednisolone 125 mg IV/IM"}],"T":[{"t":"Dark quiet room; reassess response"}],"Co":[{"t":"Discharge when relieved with outpatient follow-up; neurology if refractory"}]},"name":"Acute migraine (typical, no red flags)","level":"III","imp":"Migraine headache","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۰ ساله با سردرد ضربان‌دار یک‌طرفه، تهوع و فوتوفوبیا مشابه حملات قبلی.","why":"ضداستفراغ دوپامینی + دیفن‌هیدرامین؛ دگزامتازون کمکی."}],"ch":"140","name":"Migraine headache","name_fa":"میگرن","cc":["headache","nausea-vomiting"],"keywords":"migraine, aura, sumatriptan, DHE, metoclopramide, prochlorperazine, chlorpromazine, ketorolac, dexamethasone, میگرن","status":"draft","features":["شایع‌ترین علت خوش‌خیم سردرد در ED؛ شروع تدریجی، 4 تا 72 ساعت، معمولاً یک‌طرفه، ضربان‌دار، بدتر با فعالیت؛ تهوع، استفراغ، فوتوفوبیا و فونوفوبیا؛ با یا بدون aura"],"ddx":[{"n":"SAH / meningitis (red flags) |","cm":1},{"n":"Tension / cluster headache |"},{"n":"IIH / intracranial hypotension |"}],"redflags":["تغییر الگوی سردرد، نقص عصبی، تب، شروع ناگهانی (سردرد ثانویه)"],"guide":"درمان علامتی: dihydroergotamine (DHE)، sumatriptan، ضداستفراغ‌های آنتاگونیست دوپامین (metoclopramide، chlorpromazine، prochlorperazine) (جدول 140-4)؛ dexamethasone 6 تا 10 mg IV کمکی (کاهش عود). جدول 140-4: ketorolac 30 mg IV/IM (منع: زخم پپتیک؛ حاملگی B، پرهیز سه‌ماهه سوم)؛ metoclopramide 10 mg IV؛ prochlorperazine 5 تا 10 mg IV/PR؛ droperidol 2.5 mg IV آهسته یا IM (QT/torsades)؛ chlorpromazine 7.5 mg IV (با پیش‌درمان NS برای کاهش هیپوتانسیون)؛ همه آنتی‌دوپامین‌ها: diphenhydramine همزمان برای پیشگیری از دیستونی؛ magnesium sulfate 2 g IV طی 30 دقیقه (تأییدنشده)؛ DHE 1 mg IV طی 3 دقیقه (منع: حاملگی، IHD، HTN کنترل‌نشده، میگرن basilar/hemiplegic، sumatriptan اخیر؛ پیش‌درمان ضداستفراغ)؛ valproate 500 mg IV؛ sumatriptan 6 mg SC (منع: IHD، HTN کنترل‌نشده، basilar/hemiplegic، DHE اخیر)؛ methylprednisolone 125 mg IV/IM یا dexamethasone 6 تا 10 mg IV (کمکی/rescue).","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 140: Headache, pp. 759–764"},"cluster-headache":{"id":"cluster-headache","variants":[{"id":"cluster-main","o":{"S":[{"t":"Sumatriptan 6 mg SC for pain unresolved with oxygen","fl":[{"k":"ci","v":"ischemic heart disease, uncontrolled hypertension"}]}],"T":[{"t":"High-flow oxygen 12 L/min via nonrebreathing facemask for 15 min","fl":[{"k":"hi","v":""}]}],"Co":[{"t":"Neurology follow-up for preventive therapy"}]},"name":"Cluster headache","level":"III","imp":"Cluster headache","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","o2":"12 L/min via non-rebreather for 15 min","sc":"مرد ۳۵ ساله با درد شدید پشت چشم راست، اشک‌ریزش، گرفتگی بینی و بی‌قراری؛ هر شب مشابه.","why":"اکسیژن 12 L/min و sumatriptan."}],"ch":"140","name":"Cluster headache","name_fa":"سردرد خوشه‌ای","cc":["headache","eye"],"keywords":"cluster headache, high-flow oxygen, sumatriptan, trigeminal autonomic cephalalgia, سردرد خوشه ای","status":"draft","features":["نادر؛ درد شدید یک‌طرفه اربیتال، سوپراربیتال یا تمپورال؛ همراه: اشک‌ریزش، گرفتگی بینی، آبریزش بینی، احتقان ملتحمه و قدم زدن بی‌قرار؛ روزانه طی هفته‌ها با دوره‌های بهبود هفته تا سال"],"ddx":[{"n":"Acute angle-closure glaucoma |","cm":1},{"n":"Migraine / SAH / carotid dissection |"}],"redflags":["تغییر بینایی، نقص عصبی، شروع ناگهانی"],"guide":"اکسیژن پرجریان 12 L/min به مدت 15 دقیقه با ماسک non-rebreather؛ sumatriptan 6 mg SC برای دردی که با اکسیژن رفع نشود.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 140: Headache, pp. 759–764"},"temporal-arteritis":{"id":"temporal-arteritis","variants":[{"id":"gca-suspected","o":{"L":[{"t":"ESR, CRP, CBC, glucose"}],"S":[{"t":"Prednisone 60 mg PO daily (empiric treatment before biopsy)","fl":[{"k":"hi","v":""},{"k":"note","v":"if vision loss — urgent ophthalmology and high-dose IV steroids"}]}],"T":[{"t":"Examine temporal arteries; fundoscopy"}],"Co":[{"t":"Ophthalmology / appropriate specialist to arrange temporal artery biopsy (can be done after steroids started) and follow-up"}]},"name":"Suspected giant cell arteritis (no vision loss)","level":"II","imp":"Suspected temporal (giant cell) arteritis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۷۲ ساله با سردرد جدید تمپورال، claudication فک، تب خفیف و ESR 85.","why":"استروئید خوراکی زودهنگام قبل از بیوپسی."}],"ch":"140","name":"Temporal (giant cell) arteritis","name_fa":"آرتریت تمپورال (سلول غول‌پیکر)","cc":["headache","eye"],"keywords":"temporal arteritis, giant cell arteritis, ESR, CRP, jaw claudication, prednisone, temporal artery biopsy, آرتریت تمپورال","status":"draft","features":["معمولاً سن ≥ 50 و شیوع با سن افزایش؛ علائم: خستگی، تب، claudication فک، اختلال بینایی؛ شریان تمپورال حساس، بدون نبض یا با نبض کاهش‌یافته (یا طبیعی)","معیارهای ACR (جدول 140-3): سن شروع ≥ 50، سردرد جدید، ناهنجاری شریان تمپورال (حساسیت یا کاهش ضربان)، ESR ≥ 50 mm/h (Westergren)، بیوپسی غیرطبیعی (می‌تواند پس از شروع استروئید انجام شود): واسکولیت با ارتشاح تک‌هسته‌ای یا گرانولوماتو، سلول غول‌پیکر چندهسته‌ای","ESR و CRP در تشخیص کمک می‌کنند؛ بیوپسی تشخیص قطعی"],"ddx":[{"n":"Acute vision loss (ischemic optic neuropathy) |","cm":1},{"n":"Migraine / other secondary headache / polymyalgia rheumatica |"}],"redflags":["کاهش یا از دست رفتن بینایی (استروئید IV با دوز بالا و چشم‌پزشکی فوری)، claudication فک"],"guide":"شک بدون از دست رفتن بینایی: prednisone خوراکی 60 mg روزانه تجربی؛ مشاوره چشم‌پزشکی یا سایر تخصص‌ها برای بیوپسی شریان تمپورال و پیگیری/ادامه درمان.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 140: Headache, pp. 759–764"},"idiopathic-intracranial-hypertension":{"id":"idiopathic-intracranial-hypertension","variants":[{"id":"iih-main","o":{"I":[{"t":"CT / MRI brain and MR venography (exclude mass / CVT) before LP"}],"L":[{"t":"Lumbar puncture with opening pressure (remove CSF to reduce to 15–20 cm H2O); electrolytes, creatinine (acetazolamide); pregnancy test"}],"S":[{"t":"Acetazolamide 250–500 mg PO twice daily","fl":[{"k":"ci","v":"sulfa allergy; renal impairment"}]}],"T":[{"t":"Weight loss counseling for obese patients; visual acuity / fields"}],"Co":[{"t":"Neurology and/or ophthalmology for ongoing evaluation and treatment"}]},"name":"Idiopathic intracranial hypertension","level":"II","imp":"Idiopathic intracranial hypertension","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۲۸ ساله چاق با سردرد روزانه، تاری گذرای دید و پاپیلادم.","why":"MRI/MRV، LP با فشار باز و acetazolamide."}],"ch":"140","name":"Idiopathic intracranial hypertension (pseudotumor cerebri)","name_fa":"افزایش فشار داخل جمجمه ایدیوپاتیک (pseudotumor cerebri)","cc":["headache","eye"],"keywords":"IIH, pseudotumor cerebri, papilledema, acetazolamide, lumbar puncture opening pressure, افزایش فشار داخل جمجمه","status":"draft","features":["شایع در زنان چاق 20 تا 44 سال؛ سردرد، اختلال بینایی گذرا، درد پشت و وزوز ضربان‌دار؛ بدون درمان: از دست رفتن دائم بینایی؛ تشخیص: پاپیلادم + معاینه عصبی نرمال + فشار باز LP بالا"],"ddx":[{"n":"Cerebral venous thrombosis / mass lesion |","cm":1},{"n":"Vitamin A toxicity / medications (tetracyclines) |"}],"redflags":["از دست دادن بینایی، پاپیلادم شدید"],"guide":"acetazolamide خوراکی 250 تا 500 mg دو بار روزانه و کاهش وزن در چاقی؛ حین LP تشخیصی با برداشتن CSF اضافی فشار را به 15 تا 20 cm H2O کاهش بده؛ مشاوره نورولوژی و/یا چشم‌پزشکی.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 140: Headache, pp. 759–764"},"intracranial-hypotension-headache":{"id":"intracranial-hypotension-headache","variants":[{"id":"pdph-main","o":{"S":[{"t":"Oral hydration; IV fluids / caffeine limited evidence ; analgesics","fl":[{"k":"note","v":"symptomatic treatment"}]}],"T":[{"t":"Supine rest; analgesia"}],"Co":[{"t":"Anesthesiology: epidural blood patch (most effective) if persistent"}]},"name":"Post-dural puncture headache","level":"III","imp":"Intracranial hypotension headache (post-dural puncture)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۰ ساله 2 روز پس از بی‌حسی اپیدورال با سردرد ایستاده که با خوابیدن بهتر می‌شود.","why":"علامتی و blood patch."}],"ch":"140","name":"Post-dural puncture / intracranial hypotension headache","name_fa":"سردرد افت فشار داخل جمجمه (پس از LP / بی‌حسی اپیدورال)","cc":["headache"],"keywords":"post-dural puncture headache, intracranial hypotension, epidural blood patch, spinal headache, سردرد پس از LP","status":"draft","features":["پس از اقدام نفوذکننده دورا (LP، بی‌حسی اپیدورال)؛ بدتر در حالت ایستاده و بهتر با خوابیدن؛ تغییر شنوایی یا بینایی، تهوع و استفراغ"],"ddx":[{"n":"Meningitis / CVT / SAH |","cm":1},{"n":"Migraine |"}],"redflags":["تب، سفتی گردن، علائم عصبی کانونی"],"guide":"اغلب به درمان علامتی پاسخ می‌دهد؛ شواهد برای مایع IV و caffeine محدود؛ مؤثرترین: epidural blood patch (معمولاً توسط متخصص بیهوشی).","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 140: Headache, pp. 759–764"},"ischemic-stroke":{"id":"ischemic-stroke","variants":[{"id":"stroke-tpa-candidate","o":{"I":[{"t":"Noncontrast head CT STAT (begin ≤ 25 min, interpret ≤ 45 min from arrival); CT angiography / MRI as indicated (large vessel occlusion — endovascular therapy)"}],"L":[{"t":"Bedside glucose (STAT); CBC with platelets, PT/INR, aPTT, electrolytes, BUN, creatinine, troponin; ECG; (blood alcohol, toxicology as indicated)","fl":[{"k":"note","v":"rtPA may be given before platelet / coagulation results if no history of thrombocytopenia or anticoagulant use"}]}],"S":[{"t":"Alteplase (rtPA) 0.9 mg/kg IV (max 90 mg): 10% as bolus, remainder infused over 60 min","fl":[{"k":"hi","v":""},{"k":"ci","v":"see inclusion / exclusion criteria (Tables 141-4 / 141-5); informed consent; no aspirin or heparin for 24 h after; sICH risk 6.4%"}]},{"t":"If SBP > 185 or DBP > 110: labetalol 10–20 mg IV over 1–2 min (may repeat once) or nicardipine 5 mg/h titrated up to 15 mg/h then 3 mg/h","fl":[{"k":"ci","v":"if BP cannot be controlled, not a thrombolysis candidate; avoid rtPA with INR > 1.7, platelets < 100,000, glucose < 50"}]}],"T":[{"t":"ABC, IV access, cardiac monitoring and pulse oximetry; oxygen only if hypoxic (> 94% target); NPO until swallow screen; aspiration precautions; frequent neuro checks and BP monitoring; repeat urgent CT for any neurologic worsening (suspect ICH)"},{"t":"Determine time last known at baseline; stroke team activation within 15 min"}],"Co":[{"t":"Stroke team / neurology (emergent); interventional neuroradiology for thrombectomy; admit stroke unit / ICU (monitored)"}]},"name":"Acute ischemic stroke within window — thrombolysis candidate (< 4.5 h)","level":"I","imp":"Acute ischemic stroke, within thrombolysis window","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","o2":"only if SpO2 < 94%","sc":"مرد ۶۵ ساله با ضعف ناگهانی دست و پای راست و آفازی از 90 دقیقه پیش؛ NIHSS 12، فشار 175/100 و قند 140.","why":"CT بلافاصله و rtPA در پنجره؛ هدف فشار ≤ 185/110."},{"id":"stroke-non-candidate","o":{"I":[{"t":"Noncontrast head CT (rule out hemorrhage / mimic); CT angiography / MRI diffusion as available"}],"L":[{"t":"Bedside glucose; CBC, PT/INR, aPTT, electrolytes, BUN, creatinine, troponin; ECG; toxicology / blood alcohol as indicated"}],"S":[{"t":"Aspirin 325 mg PO within 24–48 h (not within 24 h after rtPA)","fl":[{"k":"ci","v":"active GI bleeding; do not start heparin or warfarin acutely, even with atrial fibrillation"}]},{"t":"BP: permissive hypertension, no active BP management unless SBP > 220 or DBP > 120; if needed, reduce SBP ~15% over first 24 h"}],"T":[{"t":"ABC, IV access, glucose normalization, cardiac monitor; oxygen only if SpO2 < 94%; NPO until swallow screen; aspiration prevention; fall precautions; treat comorbidities"}],"Co":[{"t":"Neurology / stroke unit admission (monitored); consider transfer to designated stroke center"}]},"name":"Acute ischemic stroke — not a thrombolysis candidate (late window / contraindicated)","level":"I","imp":"Acute ischemic stroke, not thrombolysis candidate","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","o2":"only if SpO2 < 94%","sc":"زن ۷۵ ساله با همی‌پارزی چپ از 10 ساعت قبل؛ فشار 195/105؛ INR 2.5 تحت warfarin.","why":"permissive hypertension؛ آسپرین در 24 تا 48 ساعت؛ بدون هپارین."}],"ch":"141","name":"Acute ischemic stroke","name_fa":"سکته ایسکمیک حاد","cc":["focal-neuro","headache","dizziness-vertigo"],"keywords":"stroke, ischemic stroke, rtPA, alteplase, thrombolysis, NIHSS, MCA, posterior circulation, cerebellar stroke, last known well, سکته مغزی, tPA","status":"draft","features":["سکته: هر بیماری که جریان خون مغز را مختل کند؛ ایسکمیک (87%)، ICH (10%)، SAH غیرتروماتیک (3%)؛ TIA: اختلال گذرای عصبی ناشی از ایسکمی بدون انفارکت (معمولاً < 1 تا 2 ساعت؛ مدت بی‌اعتبار؛ طیف پیوسته)","انواع (جدول 141-1): ترومبوتیک (آترواسکلروز، واسکولیت، دیسکسیون، پلی‌سیتمی، هیپرکوآگولابل، عفونت)؛ آمبولیک (وژتاسیون دریچه، ترومبوس جداری، آمبولی paradoxical، میکزوم، شریانی-شریانی، چربی، ذره‌ای، سپتیک؛ 20% از ایسکمیک‌ها، ناگهانی)؛ هیپوپرفیوژن (نارسایی قلبی/هیپوتانسیون، آسیب watershed)","یافته‌ها بسته به ناحیه مغز: ACA: ضعف و تغییر حسی پای مقابل؛ MCA: همی‌پارزی مقابل (دست > پا)، فلج صورت، از دست رفتن حس؛ آفازی در نیمکره غالب (معمولاً چپ)؛ بی‌توجهی (neglect)، دیزآرتری بدون آفازی در نیمکره غیرغالب؛ گردش خلفی (اغلب ظریف): ضعف یک‌طرفه اندام، سرگیجه، ورتیگو، تاری دید، سردرد، دیزآرتری، نقص میدان بینایی، آتاکسی راه رفتن، فلج صورت، لتارژی؛ اشغال basilar: علائم اکولوموتور، Horner و «locked-in»؛ سکته مخچه: بدتر شدن سریع با هماتوم/ادم","دیسکسیون شریان گردن: کاروتید: درد یک‌طرفه سر (68%)، گردن (39%)، صورت (10%)؛ ورتبرال: درد گردن (66%) و سردرد (65%)","فاکتورهای خطر: AF، HTN، دیابت، سیگار، آترواسکلروز کرونر، دریچه مصنوعی، MI اخیر؛ زمان آخرین وضعیت پایه (last known well) حیاتی؛ افتراق (جدول 141-3): تشنج/فلج Todd، سنکوپ، منژیت/انسفالیت، میگرن پیچیده، تومور/آبسه، ساب‌دورال/اپی‌دورال، SAH، هیپوگلیسمی، هیپوناترمی، انسفالوپاتی هیپرتانسیو، کمای هیپراسمولار، Wernicke، لابیرنتیت، مسمومیت دارو، Bell، Ménière، MS، اختلال تبدیلی","CT بدون کنتراست اورژانس (ترجیحاً تفسیر نورورادیولوژیست) برای HEM یا mimic؛ اکثر سکته‌های ایسکمیک حاد ساعات اول در CT دیده نمی‌شوند؛ NIHSS در کاندیدای ترومبولیز"],"ddx":[{"n":"Intracerebral / subarachnoid hemorrhage |","cm":1},{"n":"Hypoglycemia / seizure with Todd paralysis |","cm":1},{"n":"Migraine / meningitis / tumor / peripheral vestibular disorder |"}],"redflags":["سمپتوم < 4.5 ساعت (پنجره درمان)، NIHSS بالا، علائم گردش خلفی/مخچه، دیسکسیون"],"guide":"1) بیمار با نقص عصبی حاد: ABC، IV، قند بالین، مانیتور قلبی و پالس‌اکسیمتری؛ اکسیژن فقط در هیپوکسی با SpO2 > 94%. 2) آخرین زمان پایه عصبی. 3) پس از تثبیت: فوراً CT مغز بدون کنتراست و آزمایش از جمله انعقادی. 4) اهداف زمانی AHA/ASA از ورود: ارزیابی پزشک 10 دقیقه، فعال‌سازی تیم سکته 15، شروع CT 25، تفسیر CT 45، شروع ترومبولیتیک 1 ساعت (60 دقیقه)، پذیرش واحد سکته 3 ساعت. 5) غیرکاندید ترومبولیز: «permissive hypertension» بدون درمان فشار مگر SBP > 220 یا DBP > 120؛ در صورت نیاز کاهش SBP 15% طی 24 ساعت. 6) کاندیدای ترومبولیز: هدف SBP ≤ 185 و DBP ≤ 110 با labetalol 10 تا 20 mg IV طی 1 تا 2 دقیقه (یک تکرار) یا nicardipine 5 mg/h تا حداکثر 15 mg/h و سپس 3 mg/h؛ اگر کنترل نشد کاندید خوبی نیست. 7) rtPA IV برای ایسکمیک ≤ 3 ساعت (FDA) و 3 تا 4.5 ساعت (AHA/ASA، off-label) با معیارهای جداول 141-4 و 141-5. معیارهای ورود: تشخیص قابل‌اندازه‌گیری سکته ایسکمیک حاد (NIHSS)، شروع < 3 ساعت (آخرین وضعیت پایه)، سن ≥ 18. معیارهای خروج: تروما شدید سر یا سکته قبلی در 3 ماه، شک SAH، پونکسیون شریان غیرقابل فشار ≤ 7 روز، سابقه ICH، نئوپلاسم/AVM/آنوریسم، جراحی داخل جمجمه/نخاع اخیر، فشار > 185/110 با وجود درمان، خونریزی داخلی فعال، پلاکت < 100,000، هپارین ظرف 48 ساعت با aPTT بالا، INR > 1.7 یا PT > 15، DOAC با تست‌های آزمایشگاهی بالا، قند < 50، CT: ICH، نئوپلاسم یا انفارکت چندلوبی (> 1/3 نیمکره)؛ نسبی: سکته خفیف یا رو به بهبود سریع (مگر ناتوان‌کننده مثل آفازی/hemianopia)، بارداری، تشنج در شروع با نقص بعد از تشنج (اگر ناشی از سکته)، جراحی بزرگ/تروما 14 روز، خونریزی GI/ادراری 21 روز، MI 3 ماه؛ 3 تا 4.5 ساعت: خروج اضافی: سن > 80، سکته شدید (NIHSS > 25 یا > 1/3 MCA)، ضدانعقاد خوراکی (بدون توجه به INR)، سکته ایسکمیک قبلی + دیابت؛ قند > 400 (ECASS III، در راهنمای AHA نیست). 8) رضایت آگاهانه؛ خطر ICH علامت‌دار 6.4% (مرگ 45%) در ≤ 3 ساعت و 7.9% در 3 تا 4.5. 9) rtPA: 0.9 mg/kg IV (حداکثر 90 mg)؛ 10% بولوس، باقی طی 60 دقیقه؛ 24 ساعت اول بدون آسپرین یا هپارین؛ پایش فشار؛ بدتر شدن عصبی: CT فوری مجدد. 11) ایسکمیک: aspirin 325 mg PO در 24 تا 48 ساعت (نه ظرف 24 ساعت پس از rtPA)؛ heparin یا warfarin حاد توصیه نمی‌شود (حتی در AF). 12) حمایتی: پیشگیری آسپیراسیون، نرمال‌سازی قند، احتیاط سقوط؛ بستری مانیتور در واحد آشنا با سکته. 16) مشاوره زودهنگام نورولوژی/جراحی مغز/مراقبت ویژه نورولوژیک؛ انتقال به مرکز سکته.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 141: Stroke Syndromes and Spontaneous Subarachnoid Hemorrhage Steven Go, pp. 765–774"},"transient-ischemic-attack":{"id":"transient-ischemic-attack","variants":[{"id":"tia-main","o":{"I":[{"t":"Noncontrast CT head (MRI diffusion preferred); CT angiography / MR angiography / carotid duplex; echocardiogram as indicated"}],"L":[{"t":"Glucose (bedside), CBC, electrolytes, creatinine, PT/INR, aPTT, lipid panel, troponin; ECG (AF); pulse oximetry"}],"S":[{"t":"Aspirin 75–325 mg PO daily, or clopidogrel 75 mg PO daily, or aspirin + extended-release dipyridamole (25 mg / 200 mg twice daily)","fl":[{"k":"ci","v":"active bleeding; avoid starting heparin / warfarin in ED"}]}],"T":[{"t":"Cardiac monitoring; ABCD2 calculation; education on risk modification"}],"Co":[{"t":"Admission or expedited TIA clinic workup (ABCD2 ≥ 4 admit); neurology; discharge low-risk with explicit return precautions"}]},"name":"Transient ischemic attack","level":"II","imp":"Transient ischemic attack","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"مرد ۶۸ ساله با ضعف دست راست و اختلال گفتار 30 دقیقه که کاملاً برطرف شد؛ فشار 150/90.","why":"ورک‌آپ سریع، آنتی‌پلاکت و تعیین ABCD2."}],"ch":"141","name":"Transient ischemic attack (TIA)","name_fa":"حمله ایسکمیک گذرا (TIA)","cc":["focal-neuro","dizziness-vertigo"],"keywords":"TIA, transient ischemic attack, ABCD2, aspirin, clopidogrel, dipyridamole, carotid, حمله ایسکمیک گذرا","status":"draft","features":["اختلال گذرای عصبی از ایسکمی بدون انفارکت حاد؛ معمولاً < 1 تا 2 ساعت؛ طیف پیوسته با سکته؛ ABCD2 (جدول 141-6): سن ≥ 60 (1)، فشار ≥ 140/90 (1)، بالینی: ضعف یک‌طرفه (2) یا اختلال گفتار بدون ضعف (1)، مدت ≥ 60 دقیقه (2) یا 10 تا 59 (1)، دیابت (1)؛ خطر سکته 2 روزه: 1% (0 تا 3)، 4.1% (4 تا 5)، 8.1% (6 تا 7)"],"ddx":[{"n":"Stroke / hypoglycemia / seizure |","cm":1},{"n":"Migraine aura / syncope / vestibular disorder |"}],"redflags":["ABCD2 ≥ 4، AF، تنگی کاروتید، علائم حاضر هنگام ارزیابی"],"guide":"aspirin 75 تا 325 mg PO روزانه، clopidogrel 75 mg PO روزانه یا aspirin + dipyridamole آهسته‌رهش (25/200 mg دو بار روزانه). heparin یا warfarin در ED توصیه نمی‌شود. بستری یا شروع ورک‌آپ در ED (بر حسب منابع، وضعیت اجتماعی): برخی متخصصان بستری بیشتر TIAها را توصیه می‌کنند؛ ترخیص در بیمار کم‌خطر بدون علامت با آموزش و دستور بازگشت صریح.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 141: Stroke Syndromes and Spontaneous Subarachnoid Hemorrhage Steven Go, pp. 765–774"},"subarachnoid-hemorrhage":{"id":"subarachnoid-hemorrhage","variants":[{"id":"sah-main","o":{"I":[{"t":"Noncontrast head CT STAT; if negative: CT angiography or lumbar puncture (xanthochromia, RBC); CTA / DSA to find aneurysm"},{"t":"CXR portable"}],"L":[{"t":"CBC, PT/INR, aPTT, electrolytes, glucose, creatinine, troponin; type and screen; ECG (SAH-related changes)"}],"S":[{"t":"Labetalol 10–20 mg IV bolus over 1–2 min or infusion starting at 2 mg/min titrated; or nicardipine infusion starting 5 mg/h titrated by 2.5 mg/h to max 15 mg/h — target prehemorrhage BP or MAP < 140 mmHg if baseline unknown","fl":[{"k":"hi","v":""}]},{"t":"Nimodipine 60 mg PO every 4 h (reduces vasospasm)"},{"t":"Reverse coagulopathy: vitamin K, fresh frozen plasma, and / or prothrombin complex concentrate"}],"T":[{"t":"Airway protection / intubation if depressed consciousness; head of bed elevation; analgesia, antiemetic; seizure prophylaxis controversial (discuss with admitting specialist)"}],"Co":[{"t":"Neurosurgery (immediate); ICU admission"}]},"name":"Spontaneous SAH (suspected or confirmed)","level":"I","imp":"Subarachnoid hemorrhage","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"if SpO2 < 94%","sc":"زن ۵۰ ساله با سردرد ناگهانی «thunderclap»، استفراغ، سفتی گردن و CT: خون در شکاف سیلوین.","why":"کنترل فشار، نوروسرجری و nimodipine."}],"ch":"141","name":"Spontaneous subarachnoid hemorrhage (SAH)","name_fa":"خونریزی ساب‌آراکنوئید خودبه‌خودی (SAH)","cc":["headache","altered-mental-status","seizure"],"keywords":"subarachnoid hemorrhage, SAH, thunderclap headache, aneurysm, nimodipine, xanthochromia, CT angiography, رگ مغزی, خونریزی زیر عنکبوتیه","status":"draft","features":["کلاسیک: سردرد ناگهانی با حداکثر شدت («thunderclap»)؛ تغییر در شدت یا کیفیت نسبت به سردردهای قبلی؛ 20% با فعالیت افزایش‌دهنده فشار (مقاربت، وزنه، دفع، سرفه)؛ از دست رفتن هوشیاری، تشنج، دوبینی، استفراغ، فوتوفوبیا، سفتی گردن، تب خفیف، تغییر هوشیاری؛ علائم کانونی بسته به محل آنوریسم؛ ممکن sentinel headache («warning leak»)","علل: پارگی آنوریسم berry، پارگی malformation؛ عوامل خطر: الکل، polycystic kidney، سابقه خانوادگی، Marfan، Ehlers–Danlos؛ دیسکسیون","CT مدرن: حساسیت 98% ظرف 6 تا 12 ساعت، 91 تا 93% در 24 ساعت، 50% در یک هفته؛ CT منفی: LP (RBC، xanthochromia) توسط بسیاری؛ بعضی مطالعات: LP لازم نیست اگر CT نسل سوم < 6 ساعت توسط نورورادیولوژیست منفی؛ CT + CTA: NPV 99.4% (ضرر: تابش و آنوریسم تصادفی)"],"ddx":[{"n":"Meningitis / encephalitis |","cm":1},{"n":"Intracranial hemorrhage / CVT / dissection |","cm":1},{"n":"Migraine / cluster / tumor / drug toxicity |"}],"redflags":["thunderclap، تغییر هوشیاری، نقص کانونی، تشنج، خطر خونریزی مجدد در 24 ساعت اول"],"guide":"خطر خونریزی مجدد بیشتر در 24 ساعت اول: کنترل فشار در سطح پیش از خونریزی یا MAP < 140 mmHg اگر پایه نامعلوم؛ در صورت لزوم داروی تیتراژپذیر: labetalol 10 تا 20 mg IV طی 1 تا 2 دقیقه یا انفوزیون از 2 mg/min؛ nicardipine انفوزیون از 5 mg/h با افزایش 2.5 mg/h تا حداکثر 15 mg/h. بستری ICU با مشاوره نوروسرجری؛ nimodipine 60 mg PO هر 4 ساعت (کاهش وازواسپاسم)؛ پیشگیری تشنج بحث‌برانگیز؛ برگرداندن کوآگولوپاتی با vitamin K، FFP و/یا PCC.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 141: Stroke Syndromes and Spontaneous Subarachnoid Hemorrhage Steven Go, pp. 765–774"},"intracerebral-hemorrhage":{"id":"intracerebral-hemorrhage","variants":[{"id":"ich-main","o":{"I":[{"t":"Noncontrast head CT STAT; CT angiography (spot sign / vascular malformation) as indicated"},{"t":"CXR portable"}],"L":[{"t":"CBC, PT/INR, aPTT, electrolytes, glucose, creatinine, troponin, type and screen; toxicology (cocaine)"}],"S":[{"t":"IV antihypertensive titration (labetalol 10–20 mg IV or nicardipine infusion) for BP management","fl":[{"k":"note","v":"individualized targets per specialist"}]},{"t":"Reverse coagulopathy with vitamin K, fresh frozen plasma and / or prothrombin complex concentrate"},{"t":"Hyperglycemia management; antiepileptic medications if seizures"}],"T":[{"t":"Head elevation 30°, analgesia, sedation for increased ICP; osmotic diuretics (mannitol / hypertonic saline) or intubation with neuromuscular blockade and mild hyperventilation if more aggressive ICP reduction indicated"}],"Co":[{"t":"Neurosurgery early (increased ICP, location, surgical indication; ICP monitoring); neurocritical care ICU"}]},"name":"Intracerebral hemorrhage","level":"I","imp":"Intracerebral hemorrhage","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"if SpO2 < 94%","sc":"مرد ۶۰ ساله هیپرتانسیو با سردرد ناگهانی، استفراغ، همی‌پلژی راست و CT: هماتوم گانگلیونی.","why":"کنترل فشار، برگرداندن ضدانعقاد و نوروسرجری."}],"ch":"141","name":"Intracerebral hemorrhage (ICH)","name_fa":"خونریزی داخل مغزی (ICH)","cc":["headache","focal-neuro","altered-mental-status"],"keywords":"intracerebral hemorrhage, ICH, hypertensive hemorrhage, anticoagulant reversal, increased intracranial pressure, خونریزی داخل مغز","status":"draft","features":["خونریزی داخل پارانشیم از آرتریول‌های ضعیف‌شده؛ علل: HTN، آمیلوئیدوز، ضدانعقاد ایاتروژنیک، malformation عروقی، کوکائین؛ بالینی غیرقابل‌تفکیک از انفارکت؛ ممکن ICP بالا"],"ddx":[{"n":"Ischemic stroke |","cm":1},{"n":"SAH / tumor / abscess |"}],"redflags":["ICP بالا، کاهش هوشیاری، ضدانعقاد، توسعه خونریزی"],"guide":"بستری مراقبت ویژه مانیتورشده: ضدصرع در تشنج، مدیریت هیپرگلیسمی، مدیریت فشار، برگرداندن کوآگولوپاتی با vitamin K، FFP و/یا PCC. ICP بالا: بالا بردن سر 30°، ضددرد و آرام‌بخشی؛ اقدامات شدیدتر: دیورتیک اسمزی یا اینتوباسیون با شل‌کننده عضلانی و هایپرونتیلاسیون ملایم؛ پایش ICP تهاجمی توسط نوروسرجری. مشاوره زودهنگام نوروسرجری در ICP بالا، محل خونریزی یا شرایط نیازمند جراحی.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 141: Stroke Syndromes and Spontaneous Subarachnoid Hemorrhage Steven Go, pp. 765–774"},"delirium":{"id":"delirium","variants":[{"id":"delirium-main","o":{"I":[{"t":"CXR PA (pneumonia); CT head noncontrast if mass lesion / trauma / focal findings suspected"}],"L":[{"t":"Glucose (bedside); BMP (Na, Ca, BUN, creatinine), hepatic studies, ammonia, urinalysis (+ culture), CBC; ± troponin, TSH, blood cultures, medication / drug levels; lumbar puncture if meningitis / SAH suspected and no alternate diagnosis"}],"S":[{"t":"Treat underlying cause (e.g., IV fluids / antibiotics as indicated)","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]}],"T":[{"t":"Environmental manipulation (adequate lighting, emotional support, reorientation)"},{"t":"Agitation: haloperidol 5–10 mg PO or IM (reduced dose in elderly), or lorazepam 0.5–2 mg PO, IM, or IV","fl":[{"k":"ci","v":"avoid benzodiazepines in alcohol-unrelated delirium when possible; QT prolongation with haloperidol"}]}],"A":[{"t":"Antibiotics for identified infection (pneumonia, UTI, sepsis, meningitis per source)"}],"Co":[{"t":"Admit (unless readily reversible cause found, treated, and improved); geriatrics / medicine"}]},"name":"Delirium (acute, medical cause workup)","level":"II","imp":"Delirium","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۷۸ ساله با گیجی و بی‌قراری شبانه از 2 روز پیش، تب 38.2 و سرفه.","why":"جستجوی علت (عفونت، متابولیک، دارو)؛ آرام‌سازی در صورت لزوم."}],"ch":"142","name":"Delirium","name_fa":"دلیریوم","cc":["altered-mental-status","behavioral"],"keywords":"delirium, acute confusion, sundowning, haloperidol, lorazepam, encephalopathy, دلیریوم, گیجی حاد","status":"draft","features":["اختلال گذرا: اختلال توجه، ادراک، تفکر، حافظه و شناخت؛ طی روزها؛ چرخه خواب-بیداری مختل (خواب‌آلودگی روز، بی‌قراری شب «sundowning»)؛ هوشیاری کاهش‌یافته یا بیش‌هشیار؛ نوسان سریع؛ لرزش، asterixis، تاکی‌کاردی، تعریق، هیپرتانسیون، طغیان عاطفی و توهم","جدول 142-1: دلیریوم: شروع طی روزها، نوسان در 24 ساعت، هوشیاری کم یا بیش‌هشیار، توجه و شناخت و جهت‌یابی مختل، توهم دیداری/شنوایی، هذیان گذرا و نامنظم، asterixis/لرزش؛ دمانس: تدریجی، پایدار، هوشیار، توجه طبیعی؛ اختلال روانی: ناگهانی، پایدار، هوشیار، توهم اغلب شنوایی","جدول 142-2 علل: عفونی (پنومونی، UTI، منژیت/انسفالیت، سپسیس)؛ متابولیک/سمی (هیپوگلیسمی، الکل، اختلال الکترولیت، انسفالوپاتی کبدی، تیروئید، ترک الکل/دارو)؛ عصبی (CVA/TIA، تشنج/postictal، SAH، ICH، توده، SDH)؛ قلبی-ریوی (CHF، MI، PE، هیپوکسی/CO2 narcosis)؛ دارو (آنتی‌کولینرژیک، ترک الکل/دارو، آرام‌بخش، اوپیوئید، SSRI/SNRI، polypharmacy)","آزمایش: BMP، کبد، آمونیاک، UA، CBC، CXR؛ CT مغز اگر توده؛ LP اگر منژیت یا SAH مشکوک و تشخیص جایگزین نیست"],"ddx":[{"n":"Hypoglycemia / hypoxia / sepsis |","cm":1},{"n":"Meningitis / encephalitis / SAH / stroke / nonconvulsive status |","cm":1},{"n":"Alcohol / drug withdrawal / toxicity |"},{"n":"Dementia / psychiatric disorder |"}],"redflags":["تب، سفتی گردن، علائم کانونی، هیپوگلیسمی، هیپوکسی، ترک الکل"],"guide":"درمان بیماری زمینه‌ای مسبب؛ تغییر محیط (نور کافی و حمایت عاطفی). آژیتاسیون حاد: haloperidol 5 تا 10 mg PO یا IM (در سالمند دوز کمتر)؛ lorazepam 0.5 تا 2 mg PO، IM یا IV نیز ممکن. بستری مگر علت قابل برگشت سریع یافت، درمان شروع و بهبود دیده شود.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 142: Altered Mental Status and Coma, pp. 775–780"},"dementia-acute-change":{"id":"dementia-acute-change","variants":[{"id":"dementia-main","o":{"I":[{"t":"CT head noncontrast (SDH / hydrocephalus / mass); CXR PA if respiratory symptoms"}],"L":[{"t":"Glucose; BMP, CBC, urinalysis, TSH, vitamin B12, folate, ESR; syphilis and HIV testing if indicated"}],"S":[{"t":"(treat reversible cause; no routine IV fluids unless dehydrated)","fl":[{"k":"ci","v":"caution in heart failure"}]}],"T":[{"t":"Review medications; antipsychotic only for persistent psychosis or dangerous behavior (mind adverse reactions); environmental support"}],"Co":[{"t":"Admit if new diagnosis / unsafe; discharge if long-standing stable symptoms with consistent caregivers and reliable follow-up"}]},"name":"Dementia with acute worsening or new presentation","level":"III","imp":"Dementia, acute change in function","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"PA","sc":"مرد ۸۰ ساله با دمانس شناخته‌شده و بدتر شدن گیجی طی 3 روز؛ بدون تب.","why":"علل قابل‌درمان را بررسی کن (عفونت، دارو، متابولیک، SDH)."}],"ch":"142","name":"Dementia (acute change in function / new diagnosis)","name_fa":"دمانس (تغییر حاد عملکرد / تشخیص جدید)","cc":["altered-mental-status","behavioral"],"keywords":"dementia, Alzheimer, vascular dementia, normal pressure hydrocephalus, memory loss, دمانس, آلزایمر","status":"draft","features":["از دست رفتن تدریجی ظرفیت ذهنی؛ بزرگ‌ترین گروه‌ها: آلزایمر و دمانس عروقی؛ شروع پنهان با اختلال پیشرونده حافظه (به‌ویژه اخیر)؛ توهم، هذیان و رفتار تکراری؛ مشکل نام‌گذاری، فراموشی اشیا، از دست رفتن خواندن و جهت‌یابی، ناتوانی در خودمراقبتی، تغییر شخصیت، اضطراب، افسردگی و اختلال گفتار؛ دمانس عروقی: رفلکس تاندونی اغراق‌شده/نامتقارن، اختلال راه رفتن و ضعف اندام","معاینه ممکن است محرک یا علت تغییر حاد را بیابد؛ علائم کانونی: دمانس عروقی یا توده؛ افزایش تون و علائم اکستراپیرامیدال: Parkinson؛ NPH: بی‌اختیاری ادرار و اختلال راه رفتن + بطن‌های بزرگ در CT","مطالعات: CBC، BMP، UA، تیروئید، B12، سیفیلیس، ESR، فولات، HIV و CXR؛ CT/MRI و LP اگر تشخیص روشن نیست و فرایند داخل‌جمجمه‌ای یا عفونت CNS مشکوک؛ افتراق: دلیریوم، افسردگی و علل قابل‌درمان"],"ddx":[{"n":"Delirium / depression |","cm":1},{"n":"Normal pressure hydrocephalus / subdural hematoma |"},{"n":"B12 deficiency / hypothyroidism / neurosyphilis |"}],"redflags":["شروع حاد یا بدتر شدن سریع، علائم کانونی، خطر به خود/دیگران، تروما"],"guide":"شروع ورک‌آپ برای علل طبی بدتر شدن عملکرد؛ آنتی‌سایکوتیک برای سایکوز پایدار یا رفتار بسیار مخل/خطرناک با توجه به عوارض؛ دمانس عروقی: عوامل خطر (فشار). بسیاری از موارد جدید نیاز به بستری؛ ترخیص: علائم مزمن و پایدار، مراقبان ثابت، پیگیری سرپایی معتبر.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 142: Altered Mental Status and Coma, pp. 775–780"},"coma":{"id":"coma","variants":[{"id":"coma-undifferentiated","o":{"I":[{"t":"Noncontrast head CT STAT (then lumbar puncture if nondiagnostic and SAH / infection suspected); MRI / angiography if basilar thrombosis suspected; CXR portable"}],"L":[{"t":"Bedside glucose (STAT); BMP (Na, Ca), BUN, creatinine, liver function and ammonia, CBC, blood gas (CO2 narcosis), lactate, troponin, osmolality, ethanol and toxicology screen, APAP / salicylate, TSH / cortisol as indicated, blood cultures; EEG if nonconvulsive status suspected"}],"S":[{"t":"Dextrose (50% 50 mL IV) for hypoglycemia; thiamine 100 mg IV BEFORE glucose in alcohol abuse / malnutrition"},{"t":"Naloxone empiric (opioid toxicity)"},{"t":"If raised ICP: mannitol 0.5–1.0 g/kg IV; dexamethasone 10 mg IV for tumor-associated vasogenic edema","fl":[{"k":"ci","v":"avoid hypotension; avoid PaCO2 < 35 mmHg"}]}],"T":[{"t":"Stabilize airway (intubate for GCS ≤ 8 / airway risk), breathing, circulation; cardiac monitor"},{"t":"Raise head of bed 30° if ICP suspected; transient hyperventilation only if herniation"},{"t":"Consider nonconvulsive status epilepticus (EEG) if seizure and not returned to baseline; examine for trauma, toxidromes"}],"A":[{"t":"Empiric antibiotics ± acyclovir if meningitis / encephalitis suspected (do not delay for LP / CT)"}],"Co":[{"t":"Neurology / neurosurgery / ICU admission; toxicology if ingestion; pediatrics: consider toxic ingestion, infection, nonaccidental trauma"}]},"name":"Coma, undifferentiated (empiric reversible causes, CT)","level":"I","imp":"Coma, undifferentiated","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate to SpO2 ≥ 94%","sc":"مردی ۵۵ ساله بدون سابقه یافت‌شده بی‌پاسخ، GCS 6، مردمک 2 mm واکنش‌دار، فشار 130/80.","why":"گلوکز، نالوکسان، تیامین، CT و جستجوی علت."}],"ch":"142","name":"Coma","name_fa":"کما","cc":["altered-mental-status"],"keywords":"coma, Glasgow Coma Scale, GCS, FOUR score, unresponsive, naloxone, thiamine, increased ICP, mannitol, pseudocoma, nonconvulsive status epilepticus, کما, گلاسگو","status":"draft","features":["حالت کاهش هوشیاری و پاسخ‌دهی که بیمار قابل بیدار شدن نیست؛ GCS (جدول 142-3) و FOUR score؛ مردمک، اعصاب کرانیال، همی‌پارزی و پاسخ به تحریک → دسته: اختلال منتشر CNS (سمی-متابولیک) یا کانونی (ساختاری)","سمی-متابولیک: بدون یافته کانونی؛ مردمک معمولاً کوچک و واکنش‌دار (ممکن بزرگ در مسمومیت شدید آرام‌بخش مثل باربیتورات)","ضایعه supratentorial: همی‌پارزی پیشرونده یا تون/رفلکس نامتقارن؛ ICP بالا: رفلکس Cushing (هیپرتانسیون و برادیکاردی)؛ posterior fossa/infratentorial: شروع ناگهانی، اکستانسور پوسچرینگ، از دست رفتن رفلکس مردمک و حرکات چشم؛ هموراژی pons: مردمک نقطه‌ای","pseudocoma: مردمک، حرکات چشم، تون و رفلکس سالم؛ مقاومت در باز کردن چشم، اجتناب از نگاه، nystagmus در تست کالریک ← غیرفیزیولوژیک","شروع ناگهانی: سکته فاجعه‌بار یا status؛ تدریجی: متابولیک یا ضایعه پیشرونده؛ تست‌های عصبی ظریف ممکن نیست؛ مردمک نامتقارن، رفلکس قرنیه و oculovestibular؛ پوسچرینگ اکستانسور/فلکسور ← اختلال عمیق CNS","CT سر و سپس LP اگر غیرتشخیصی و SAH یا عفونت مشکوک؛ ترومبوز basilar: MRI یا آنژیوگرافی؛ بعد از تشنج و بیدار نشدن: nonconvulsive status → EEG؛ در کودک: مسمومیت، عفونت، تروما غیرتصادفی","جدول 142-4 علل: منتشر: انسفالوپاتی (هیپوکسیک، متابولیک، هیپرتانسیو)، هیپوگلیسمی، حالت هیپراسمولار، اختلال الکترولیت، نارسایی عضو (کبد/اورمی)، اندوکرین (آدیسون، هیپوتیروئیدی)، هیپوکسی، CO2 narcosis، سم/دارو (NMS)، محیطی (هیپو/هیپرترمی)، Wernicke، سپسیس؛ CNS اولیه/تروما: DAI، SDH/EDH، خونریزی پارانشیم (نیمکره، گانگلیون‌های بازال، ساقه، مخچه)، SAH، انفارکت، عفونت CNS، نئوپلاسم، تشنج (NCSE، postictal)"],"ddx":[{"n":"Hypoglycemia / opioid overdose / hypoxia / CO2 narcosis |","cm":1},{"n":"Intracranial hemorrhage / stroke / nonconvulsive status epilepticus |","cm":1},{"n":"Meningitis / encephalitis / sepsis / toxic-metabolic encephalopathy |"},{"n":"Psychogenic coma (pseudocoma) |"}],"redflags":["GCS ≤ 8، مردمک نامتقارن/ثابت، Cushing reflex، پوسچرینگ، تب با سفتی گردن"],"guide":"حمایتی و شناسایی علت. 1) ثبات ABC. 2) درمان علل برگشت‌پذیر: هیپوگلیسمی و مسمومیت اپیوئید؛ naloxone تجربی؛ thiamine قبل از گلوکز در الکلی یا سوءتغذیه. 3) NCSE را در بیمار بعد از تشنج که به پایه نرسیده در نظر بگیر. 4) ICP بالا: سر 30°، mannitol 0.5 تا 1.0 g/kg؛ dexamethasone 10 mg IV برای ادم واژوژنیک تومور؛ هایپرونتیلاسیون موقت ICP را کم می‌کند؛ PaCO2 زیر 35 mmHg نرود. 5) ترخیص: علت کاملاً رفع‌شده و مراقبت/پیگیری کافی؛ در غیر این صورت بستری.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 142: Altered Mental Status and Coma, pp. 775–780"},"ataxia-gait-disturbance":{"id":"ataxia-gait-disturbance","variants":[{"id":"ataxia-acute","o":{"I":[{"t":"CT head noncontrast (cerebellar hemorrhage / infarct) → MRI brain if CT negative and posterior circulation suspected; MRI spine if cord compression / myelopathy"}],"L":[{"t":"Glucose (bedside); BMP (Na), ethanol and drug levels (phenytoin, carbamazepine, valproate) as indicated, CBC, vitamin B12, magnesium, liver function; VDRL / RPR; lumbar puncture if CNS infection suspected"}],"S":[{"t":"Thiamine 100 mg IV (alcoholics and malnourished adults, before glucose)","fl":[{"k":"hi","v":""}]},{"t":"Electrolyte correction (hyponatremia etc.)"}],"T":[{"t":"Observe gait; orthostatic vital signs; cardiac / neuro checks; fall precautions"}],"Co":[{"t":"Admit patients with acute unexplained inability to walk; neurology; toxicology if ingestion"}]},"name":"Acute ataxia / gait disturbance, unexplained (central vs systemic vs toxic)","level":"II","imp":"Acute ataxia / gait disturbance","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"مرد ۵۰ ساله الکلی با راه رفتن ناپایدار، دوبینی، نیستاگموس و گیجی از 2 روز پیش.","why":"تیامین فوری؛ CT/MRI برای ضایعه مخچه."},{"id":"gait-chronic-b12-nph","o":{"I":[{"t":"CT head (ventriculomegaly — NPH); MRI as indicated"}],"L":[{"t":"Vitamin B12 level and CBC; VDRL / RPR; TSH, BMP, glucose"}],"T":[{"t":"Observe ambulation (rise from chair, heel / toe walk, tandem); fall-prevention counseling"}],"Co":[{"t":"Neurology follow-up (Parkinson's disease / NPH); admit if unable to ambulate safely"}]},"name":"Subacute gait disturbance — B12 deficiency / neurosyphilis / normal pressure hydrocephalus / Parkinson","level":"III","imp":"Gait disturbance, subacute (B12 deficiency / NPH / Parkinson)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۷۵ ساله با راه رفتن گشاد و آهسته، بی‌اختیاری ادرار و فراموشی؛ یا بی‌حسی انگشتان پا با Romberg مثبت.","why":"CT برای NPH و B12/VDRL؛ ارجاع."}],"ch":"143","name":"Ataxia and gait disturbances (incl. Wernicke–Korsakoff, B12 deficiency)","name_fa":"آتاکسی و اختلالات راه رفتن","cc":["dizziness-vertigo","weakness","focal-neuro"],"keywords":"ataxia, gait disturbance, Romberg, cerebellar ataxia, sensory ataxia, Wernicke encephalopathy, thiamine, B12 deficiency, normal pressure hydrocephalus, آتاکسی, راه رفتن, ورنیکه","status":"draft","features":["آتاکسی: حرکت ناهماهنگ؛ اختلال راه رفتن: الگوی غیرطبیعی؛ در بسیاری بیماری‌ها؛ ابتدا ببین ثانویه به بیماری سیستمیک است (سردرد، تهوع، تب، کاهش هوشیاری؛ تغییر علائم ارتواستاتیک)","ارزیابی آتاکسی اولیه: موتور مخچه‌ای در برابر حسی: dysmetria (finger-to-nose)؛ dysdiadochokinesia؛ heel-to-shin: overshoot ← مخچه، مسیر لرزان ← نقص proprioception؛ Romberg: بی‌ثباتی با چشم باز ← مخچه‌ای؛ بدتر با چشم بسته ← حسی؛ ارتعاش و حس موقعیت (tabes dorsalis، کمبود B12)؛ مشاهده راه رفتن: ضعف پروگزیمال/دیستال، tandem، heel/toe؛ گام پایه گشاد = آتاکسی موتور؛ آتاکسی حسی: حرکات ناگهانی و کوبیدن پا؛ senile gait (آهسته، گشاد، کوتاه)؛ Parkinson: festinating گام کوتاه؛ foot drop: equine gait","جدول 143-1 علل حاد: مسمومیت (اتانول، آرام‌بخش، phenytoin، carbamazepine، valproate، فلزات)، متابولیک (هیپوناترمی، اختلال ارثی متابولیسم، Wernicke)؛ مخچه (خونریزی، انفارکت، دژنراتیو، آبسه)، قشر (تومور/خونریزی/تروما فرونتال، هیدروسفالی)، ساب‌کورتیکال (تالاموس، Parkinson، NPH)، نخاع (spondylosis و فشار نخاع، ستون خلفی)، نوروپاتی محیطی، وستیبولوپاتی","Wernicke: آتاکسی، تغییر هوشیاری، افتالموپلژی (نیستاگموس شایع‌ترین یافته چشمی)؛ کلاسیک در الکلی ولی در هر فرد سوءتغذیه؛ Korsakoff: confabulation؛ B12: از دست رفتن حس موقعیت انگشت دوم پا + Romberg مثبت؛ سطح B12 و CBC (نورولوژیک اغلب مقدم بر آنمی ماکروسیتیک)؛ نوروسیفیلیس: VDRL/RPR","کودک: مسمومیت شایع؛ 2 تا 4 سال: پس از واکسن/ویروس/واریسلا؛ توده posterior fossa؛ opsoclonus-myoclonus ← نوروبلاستوما"],"ddx":[{"n":"Cerebellar stroke / hemorrhage |","cm":1},{"n":"Wernicke encephalopathy |","cm":1},{"n":"Drug toxicity (phenytoin, carbamazepine, alcohol) / hyponatremia |"},{"n":"B12 deficiency / neurosyphilis / NPH / spinal cord compression |"}],"redflags":["شروع ناگهانی، سردرد، تهوع، کاهش هوشیاری، نیستاگموس مرکزی، عدم توانایی ناگهانی راه رفتن"],"guide":"میزان ارزیابی ED با حدت و شدت علائم؛ شروع حاد یا پیشرفت اخیر ورک‌آپ وسیع‌تر. CT یا MRI در صورت اندیکاسیون؛ LP برای شک عفونت CNS. 1) thiamine 100 mg IV برای الکلی و بزرگسال سوءتغذیه با احتمال Wernicke–Korsakoff. 2) بستری بیمار با ناتوانی حاد و بی‌توضیح در راه رفتن برای ارزیابی و تست.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 143: Ataxia and Gait Disturbances, pp. 781–783"},"vertigo-undifferentiated":{"id":"vertigo-undifferentiated","variants":[{"id":"vertigo-central-suspected","o":{"I":[{"t":"Noncontrast CT head (hemorrhage); MRI brain with diffusion (preferred for posterior circulation infarct; CT insensitive) and MR / CT angiography (vertebrobasilar, dissection)"}],"L":[{"t":"Glucose (bedside); CBC, electrolytes, BUN / creatinine, PT/INR, aPTT, troponin; ECG (AF)"}],"S":[{"t":"Antiemetic (ondansetron 4 mg IV) for symptom relief","fl":[{"k":"ci","v":"avoid neuroleptics in orthostatic patients"}]}],"T":[{"t":"Cardiac monitor; neuro checks; HINTS exam (head impulse, nystagmus, test of skew) and gait / truncal ataxia assessment","fl":[{"k":"ci","v":"avoid head / neck twisting maneuvers if cervical artery dissection suspected"}]},{"t":"See ischemic stroke / TIA protocol (antiplatelet, thrombolysis candidacy) when confirmed"}],"Co":[{"t":"Neurology (emergent); neurosurgery for posterior fossa hemorrhage / tumor; admit monitored"}]},"name":"Suspected central vertigo (HINTS central / red flags) — stroke workup","level":"I","imp":"Acute vertigo, suspected central cause (posterior circulation stroke)","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","o2":"only if SpO2 < 94%","sc":"مرد ۶۵ ساله هیپرتانسیو با ورتیگوی ناگهانی، سردرد، استفراغ، آتاکسی تنه و نیستاگموس عمودی؛ HINTS مرکزی.","why":"سکته خلفی را زود رد کن؛ MRI/CTA و مشاوره نورولوژی."},{"id":"vertigo-peripheral-symptomatic","o":{"L":[{"t":"(no routine labs; glucose bedside; electrolytes if vomiting)"}],"S":[{"t":"Diphenhydramine 25–50 mg IM, IV, or PO; meclizine 25 mg PO","fl":[{"k":"ci","v":"drowsiness / anticholinergic effects; caution in elderly"}]},{"t":"Ondansetron 4 mg IV for vomiting; IV fluids if dehydrated","fl":[{"k":"ci","v":"caution in heart failure"}]},{"t":"Second-line: calcium antagonists, neuroleptics (not in orthostatic patients); benzodiazepines sparingly (diazepam 2–5 mg)","fl":[{"k":"note","v":"benzodiazepines impair vestibular rehabilitation"}]}],"T":[{"t":"Symptomatic treatment; fall precautions; early ambulation; transdermal scopolamine 0.5 mg best as discharge medication (onset 4–8 h)","fl":[{"k":"note","v":"methylprednisolone and antivirals of no proven benefit for vestibular neuronitis"}]}],"Co":[{"t":"Discharge with follow-up; ENT referral if suspected perilymph fistula or bacterial labyrinthitis"}]},"name":"Acute peripheral vertigo — vestibular neuronitis / labyrinthitis (symptomatic)","level":"III","imp":"Acute peripheral vertigo (vestibular neuronitis / labyrinthitis)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۴۰ ساله با ورتیگوی شدید ناگهانی، تهوع و استفراغ بعد از عفونت تنفسی؛ نیستاگموس افقی یک‌طرفه، head impulse غیرطبیعی و بدون علائم CNS.","why":"علامتی؛ HINTS محیطی."},{"id":"vertigo-bppv","o":{"T":[{"t":"Dix–Hallpike maneuver (patient seated, head turned 45°, lower rapidly supine with head hanging 20°; positive: short-lived rotatory nystagmus beating toward dependent ear)"},{"t":"Epley maneuver: seated, head 45° toward affected ear → supine head hanging 20° (wait 30–60 s) → rotate head 90° to unaffected side (30–60 s) → roll onto unaffected shoulder with head turned further 90° nearly facedown (30–60 s) → sit upright; may repeat","fl":[{"k":"ci","v":"avoid in cervical artery dissection / vertebrobasilar insufficiency / spinal pathology"}]},{"t":"If unsuccessful: vestibular rehabilitation exercises; antiemetics or antivertigo drugs as adjunct"}],"Co":[{"t":"Discharge; ENT / neurology follow-up if recurrent"}]},"name":"Benign paroxysmal positional vertigo (BPPV) — Dix–Hallpike / Epley","level":"III","imp":"Benign paroxysmal positional vertigo","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۵۵ ساله با ورتیگوی کوتاه (< 1 دقیقه) هنگام چرخش در تخت؛ Dix–Hallpike مثبت سمت راست.","why":"مانور Epley درمان قطعی."},{"id":"vertigo-menieres","o":{"L":[{"t":"(audiometry outpatient; no routine labs)"}],"S":[{"t":"Antihistamines / antiemetics (meclizine 25 mg PO; ondansetron 4 mg IV); diuretics; betahistine 48 mg PO three times daily for 6–12 months (Ménière)"}],"T":[{"t":"Low-salt diet (< 1 g added salt/day); avoid ototoxic drugs (NSAIDs, salicylates, aminoglycosides, loop diuretics, cytotoxics); pneumatic otoscopy for perilymph fistula"}],"Co":[{"t":"ENT referral (Ménière diagnosis needs multiple episodes with progressive hearing loss; perilymph fistula)"}]},"name":"Ménière syndrome / perilymph fistula / ototoxic vertigo","level":"III","imp":"Ménière syndrome / perilymph fistula","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۵۰ ساله با حملات راجعه ورتیگو، وزوز یک‌طرفه و کاهش شنوایی؛ یا ورتیگوی ناگهانی هنگام غواصی/بلند کردن بار.","why":"علامتی؛ ENT برای fistula."},{"id":"vertigo-ramsay-hunt","o":{"S":[{"t":"Antiviral agents (e.g., valacyclovir 1000 mg PO three times daily for 7 days)","fl":[{"k":"ci","v":"dose adjust in renal impairment"}]},{"t":"Antiemetic / antihistamine for vertigo"}],"T":[{"t":"Eye protection for facial palsy; analgesia"}],"Co":[{"t":"ENT / neurology follow-up"}]},"name":"Ramsay Hunt syndrome / vestibular ganglionitis","level":"III","imp":"Ramsay Hunt syndrome (herpes zoster oticus)","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۶۵ ساله با ورتیگو، کم‌شنوایی، فلج صورت و وزیکول در مجرای گوش خارجی.","why":"درمان ضدویروس؛ نورونیت ویروسی نوروتروپیک."}],"ch":"144","name":"Acute vertigo — peripheral vs central (HINTS)","name_fa":"ورتیگو حاد — محیطی در برابر مرکزی (HINTS)","cc":["dizziness-vertigo"],"keywords":"vertigo, HINTS exam, head impulse, nystagmus, test of skew, central vertigo, peripheral vertigo, posterior circulation stroke, ورتیگو, سرگیجه, HINTS","status":"draft","features":["ورتیگو: ادراک حرکت در نبود حرکت؛ ناشی از عدم تطابق سیستم‌های دیداری، وستیبولار و پروپریوسپتیو؛ «اتاق می‌چرخد»؛ محیطی (دستگاه وستیبولار و عصب هشتم): شروع ناگهانی، شدید، تهوع، استفراغ، عدم تحمل حرکت سر، تعریق؛ مرکزی (ساقه/مخچه): ناگهانی یا تدریجی، معمولاً خفیف‌تر و کم‌تعریف","جدول 144-1 محیطی در برابر مرکزی: شروع: ناگهانی یا پنهان | ناگهانی؛ شدت: چرخشی شدید | کم‌تعریف و کمتر؛ پیش‌علامت: تا 25% معمولاً یک دوره | تا 25% و دوره‌های راجعه ← TIA؛ عدم تحمل حرکت سر/Dix–Hallpike: بله | گاه؛ تهوع/تعریق: شایع | متغیر؛ علائم شنوایی: به محیطی اشاره می‌کند | ممکن؛ تناسب علائم: معمولاً متناسب | اغلب نامتناسب؛ سردرد/درد گردن: غیرمعمول | محتمل‌تر؛ نیستاگموس: چرخشی-عمودی، افقی | عمودی؛ علائم CNS: ندارد | معمولاً دارد؛ head impulse: غیرطبیعی | معمولاً طبیعی؛ HINTS: علائم محیطی در هر سه | علائم مرکزی در حداقل یکی","HINTS: Head Impulse (VOR)، Nystagmus با جهت متغیر با نگاه، Test of Skew (انحراف عمودی با cover-uncover)؛ یک یا چند یافته مرکزی در HINTS (توسط متخصص) برای سکته حساس و اختصاصی؛ Dix–Hallpike برای BPPV (حساسیت 75 تا 82%)؛ مانورهای چرخش سر/گردن در دیسکسیون شریان گردن، VBI یا آسیب ستون ممنوع","جدول 144-2 علل: وستیبولار/اتولوژیک (BPPV، تروما، عفونت: لابیرنتیت، نورونیت وستیبولار، Ramsay Hunt، Ménière، otosclerosis، Paget، سمی: aminoglycoside)؛ عصبی (VBI یا دیسکسیون ورتبرال، Wallenberg، AICA، تومور زاویه پونتوسربلار، مخچه، گانگلیون‌های بازال، MS، عفونت، صرع، میگرن، عروقی)؛ سیستمیک/عمومی (خونی: کم‌خونی، پلی‌سیتمی، هیپرویسکوزیته؛ سمی: الکل؛ نارسایی کلیه؛ متابولیک: تیروئید، هیپوگلیسمی)","آزمایش در ورتیگوی محیطی معمول نیست؛ تصویربرداری (CT، CTA، MRI/MRA) در شک مرکزی: سالمند با علائم عصبی/مخچه‌ای، عوامل خطر سکته، کوآگولوپاتی/ضدانعقاد، سردرد، تروما سر/گردن، علائم پایدار > 72 ساعت"],"ddx":[{"n":"Cerebellar / brainstem stroke or hemorrhage (posterior circulation) |","cm":1},{"n":"Vertebral artery dissection |","cm":1},{"n":"Peripheral vestibulopathy (BPPV, neuronitis, labyrinthitis, Ménière) |"},{"n":"Acoustic neuroma / MS / vestibular migraine / hypoglycemia / drug toxicity |"}],"redflags":["HINTS مرکزی، سردرد/درد گردن، علائم کرانیال/مخچه‌ای، ضدانعقاد، سن بالا و عوامل خطر عروقی، نقص عصبی"],"guide":"شکل 144-1 رویکرد: LOC: سنکوپ، تشنج، فرایند داخل‌جمجمه‌ای ← ECG، تصویربرداری، الکترولیت، بستری. ورتیگوی واقعی با علائم CNS: CT/MRI/MRA و بستری و ارجاع نورولوژی/نوروسرجری. بدون علائم CNS: مدت: دقیقه (TIA: بررسی کاروتید، اکو، آنتی‌پلاکت/ضدانعقاد)؛ ناشی از حرکات ناگهانی سر ← BPPV؛ کاهش شنوایی ← URI/اوتیت (لابیرنتیت باکتریال: CT/MRI، آنتی‌بیوتیک، ENT) یا وزوز (neuroma آکوستیک: CT/MRI و جراحی/ENT) یا Ménière (آنتی‌هیستامین/ضداستفراغ، دیورتیک، نمک < 1 g/روز، ENT)؛ سایر: نورونیت وستیبولار (آنتی‌هیستامین/ضداستفراغ، اطمینان). دارودرمانی (جدول 144-4): anticholinergic: scopolamine 0.5 mg ترانس‌درمال (پشت گوش) 3 تا 4 بار روزانه؛ آنتی‌هیستامین: dimenhydrinate 50 تا 100 mg IM/IV/PO هر 4 ساعت؛ diphenhydramine 25 تا 50 mg IM/IV/PO؛ meclizine 25 mg PO؛ hydroxyzine 25 mg 2 تا 4 بار؛ ضداستفراغ: metoclopramide 10 mg؛ ondansetron 4 mg IV؛ promethazine 25 mg IM/PO/PR؛ بنزودیازپین: diazepam 2 تا 5 mg؛ clonazepam 0.5 mg دو بار؛ مسدودکننده کلسیم: cinnarizine 25 mg PO؛ nimodipine 30 mg؛ flunarizine 20 mg؛ وازودیلاتور betahistine 48 mg سه بار تا 6 تا 12 ماه (Ménière)؛ کورتیکواستروئید methylprednisolone 100 mg/d با کاهش 20 mg هر 4 روز (نورونیت)؛ ضدویروس valacyclovir 1000 mg سه بار 7 روز (نورونیت)؛ ضدتشنج: carbamazepine 200 تا 600 mg/d، topiramate 50 تا 100، valproate 300 تا 900، gabapentin 300 mg چهار بار؛ β-blocker: metoprolol 100 mg/d.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 144: Acute Vertigo, pp. 784–791"},"seizure-adult-first-or-known":{"id":"seizure-adult-first-or-known","variants":[{"id":"seizure-first-uncomplicated","o":{"I":[{"t":"Noncontrast head CT (first seizure or change in seizure pattern); MRI as outpatient"}],"L":[{"t":"Glucose, BMP (Na), calcium, magnesium; pregnancy test; toxicology / alcohol as indicated; CBC; anticonvulsant levels if known epilepsy","fl":[{"k":"note","v":"serum prolactin / CK not routine"}]}],"S":[{"t":"(no IV anticonvulsant needed if seizure resolved spontaneously)"}],"T":[{"t":"Protect from injury / aspiration during active seizure; seizure precautions; observe until return to baseline"},{"t":"Counseling: no swimming, hazardous tools / machinery, working at heights; no driving until cleared by neurologist / physician per state law"}],"Co":[{"t":"Discharge with outpatient neurology follow-up (antiepileptic initiation, MRI deferred) if normal exam, mental status, comorbidity-free and normal testing; admit otherwise"}]},"name":"First seizure, resolved, normal exam (discharge pathway)","level":"III","imp":"First seizure, adult, resolved","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"مرد ۳۰ ساله با اولین تشنج منتشر 2 دقیقه‌ای با گیجی postictal که اکنون کاملاً هوشیار است؛ معاینه عصبی طبیعی.","why":"علل ثانویه را رد و ترخیص با پیگیری."},{"id":"seizure-known-epilepsy","o":{"L":[{"t":"Glucose; anticonvulsant levels (e.g., phenytoin, valproate, carbamazepine); BMP; pregnancy test"}],"S":[{"t":"Supplemental dose of anticonvulsant if levels low / missed doses: phenytoin 20 mg/kg IV at ≤ 25 mg/min (or oral load divided in 3 doses every 2–4 h); fosphenytoin 20 PE/kg at ≤ 150 PE/min","fl":[{"k":"ci","v":"phenytoin infusion — cardiac monitoring; hypotension / bradycardia"}]}],"T":[{"t":"Seizure precautions; review compliance and precipitants (sleep deprivation, alcohol, drugs)"}],"Co":[{"t":"Discharge with neurology follow-up if back to baseline; CT head if change in seizure pattern or head injury"}]},"name":"Breakthrough seizure in known epilepsy (low levels / missed doses)","level":"III","imp":"Breakthrough seizure, known seizure disorder","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۴۰ ساله مبتلا به صرع تحت phenytoin که 2 روز دوز را فراموش کرده و تشنج منتشر تیپیک داشته؛ اکنون هوشیار.","why":"سطح دارو، دوز مکمل و ترخیص."}],"ch":"145","name":"Seizure in adults (first seizure and known seizure disorder)","name_fa":"تشنج در بزرگسالان (اولین تشنج و صرع شناخته‌شده)","cc":["seizure"],"keywords":"seizure, first seizure, epilepsy, generalized tonic-clonic, postictal, Todd paralysis, provoked seizure, anticonvulsant level, تشنج, صرع","status":"draft","features":["تشنج: دوره اختلال عملکرد عصبی از تخلیه الکتریکی نامناسب نورون‌ها؛ اولیه (بدون علت مشخص) و ثانویه (توده، ضربه سر، سکته) (جدول 145-1: تروما، خونریزی داخل‌جمجمه‌ای، ضایعات ساختاری CNS (عروقی، توده، دژنراتیو، مادرزادی)، عفونت (منژیت، انسفالیت، آبسه)، متابولیک (قند، Na، هیپراسمولار، اورمی، نارسایی کبد، Ca/Mg)، سموم/دارو (کوکائین، lidocaine، ضدافسردگی، theophylline، INH، Gyromitra، hydrazine)، ترک الکل/دارو، اکلامپسی تا 8 هفته پس از زایمان، انسفالوپاتی هیپرتانسیو، آسیب ایسکمیک-آنوکسیک)","منتشر (grand mal): از دست رفتن ناگهانی هوشیاری؛ فاز سفتی (tonic) سپس تکان‌های ریتمیک متقارن (clonic)؛ بی‌اختیاری؛ فاز postictal شل؛ 60 تا 90 ثانیه؛ گیجی postictal تا ساعت‌ها؛ absence (petit mal): کودک مدرسه، چند ثانیه، بدون از دست رفتن تون؛ جزئی: ساده (هوشیاری سالم) و پیچیده (تغییر هوشیاری؛ لوب تمپورال؛ automatism، توهم، اختلال حافظه)؛ فلج Todd: نقص کانونی گذرا پس از تشنج کانونی (تا 48 ساعت)","تشخیص: شرح حال دقیق (aura، شروع، پیشرفت، بی‌اختیاری، کانونی/منتشر، مدت، postictal)، سابقه سردرد مداوم/شدید/ناگهانی (فرایند داخل‌جمجمه‌ای)؛ در صرع شناخته: قند و سطح داروها؛ اولین تشنج بزرگسال: قند، BMP، Ca، Mg، تست بارداری، توکسیکولوژی؛ CT بدون کنتراست در اولین تشنج یا تغییر الگو؛ MRI سرپایی؛ LP در شک عفونت یا SAH؛ افتراق: سنکوپ، pseudoseizure، سندرم هیپرونتیلاسیون، اختلال حرکتی، میگرن"],"ddx":[{"n":"Hypoglycemia / hyponatremia / eclampsia / toxic cause |","cm":1},{"n":"Intracranial hemorrhage / mass / CNS infection |","cm":1},{"n":"Syncope / psychogenic nonepileptic seizure |"},{"n":"Alcohol or drug withdrawal |"}],"redflags":["تشنج اول در بزرگسال، سردرد شدید، تب و سفتی گردن، نقص کانونی، بارداری/پس از زایمان، ترک الکل، ضدانعقاد"],"guide":"در تشنج فعال: محافظت از آسیب و آسپیراسیون؛ ضدتشنج IV در تشنج بدون عارضه که خودبه‌خود فروکش می‌کند اغلب لازم نیست. صرع شناخته با سطح پایین یا دوز فراموش‌شده: دوز مکمل. phenytoin خوراکی 20 mg/kg در 3 دوز هر 2 تا 4 ساعت وقت‌گیر است؛ جایگزین: phenytoin 20 mg/kg IV با سرعت 25 mg/min؛ fosphenytoin 20 PE/kg حداکثر 150 PE/min. اکلامپسی: magnesium sulfate IV و مشاوره زودهنگام زنان. ترخیص بیمار با اولین تشنج: معاینه عصبی طبیعی، بدون بیماری همراه حاد/مزمن، تست و تصویربرداری طبیعی و وضعیت ذهنی طبیعی؛ شروع ضدصرع، MRI و تست‌های بیشتر می‌تواند سرپایی. توصیه‌ها: پرهیز از شنا، ابزار/ماشین خطرناک و کار در ارتفاع؛ رانندگی تا مجوز نورولوژیست/پزشک و طبق قانون.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 145: Seizures and Status Epilepticus in Adults, pp. 792–795"},"status-epilepticus":{"id":"status-epilepticus","variants":[{"id":"status-epilepticus-main","o":{"I":[{"t":"Noncontrast head CT after stabilization; CXR portable (aspiration)"},{"t":"EEG (continuous if refractory or nonconvulsive status suspected)"}],"L":[{"t":"Point-of-care glucose (STAT); BMP (Na, Ca, Mg), CBC, blood gas, lactate, CK, anticonvulsant levels, toxicology / alcohol, pregnancy test; LP if CNS infection suspected"}],"S":[{"t":"Dextrose IV if hypoglycemia (thiamine 100 mg IV first if alcohol abuse / malnutrition)"},{"t":"Lorazepam IV 2 mg up to 0.1 mg/kg (repeat once) or diazepam IV 10–20 mg — first line (goal 5–10 min)","fl":[{"k":"hi","v":""}]},{"t":"Then one of: fosphenytoin 20 PE/kg IV at ≤ 150 PE/min; phenytoin 20 mg/kg IV at ≤ 50 mg/min; levetiracetam 2000–4000 mg IV; phenobarbital 20 mg/kg IV at 50–75 mg/min","fl":[{"k":"ci","v":"phenytoin / fosphenytoin — cardiac monitoring for hypotension / dysrhythmia"}]},{"t":"Refractory (goal < 30 min): midazolam IV load 0.2 mg/kg then infusion 0.05–2 mg/kg/h; or propofol 1 mg/kg then 1–10 mg/kg/h; or ketamine; pentobarbital","fl":[{"k":"note","v":"intubate; short-acting paralytic only"}]}],"T":[{"t":"IV access, cardiac monitor, pulse oximetry, airway maintenance (intubation as required), oxygen; protect from injury"},{"t":"If paralytic used: short-acting agent so ongoing seizure activity can be monitored; otherwise EEG monitoring"},{"t":"Isoniazid toxicity: pyridoxine; eclampsia: magnesium sulfate","fl":[{"k":"note","v":"see specific causes"}]}],"Co":[{"t":"Neurology early; neuro ICU admission with continuous EEG if refractory"}]},"name":"Status epilepticus (adult)","level":"I","imp":"Status epilepticus","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"high-flow oxygen","sc":"مرد ۴۵ ساله با تشنج منتشر مداوم 8 دقیقه بدون بازگشت هوشیاری.","why":"لورازپام IV بلافاصله؛ سپس خط دوم؛ راه هوایی و علت."}],"ch":"145","name":"Status epilepticus (convulsive and nonconvulsive)","name_fa":"ایستای صرعی (Status epilepticus)","cc":["seizure","altered-mental-status"],"keywords":"status epilepticus, refractory status, lorazepam, diazepam, fosphenytoin, levetiracetam, midazolam, propofol, phenobarbital, EEG, استاتوس اپی‌لپتیکوس, لورازپام","status":"draft","features":["تشنج واحد > 5 دقیقه یا دو یا چند تشنج متوالی بدون بازگشت هوشیاری؛ nonconvulsive: تغییر هوشیاری بدون فعالیت عضلانی قابل‌مشاهده؛ با EEG تأیید می‌شود","علل: جدول 145-1 (قند، Na، تروما/خونریزی، توده، عفونت، سم، ترک، اکلامپسی، HTN، آنوکسی)"],"ddx":[{"n":"Hypoglycemia / eclampsia / toxic seizure (isoniazid, theophylline) |","cm":1},{"n":"CNS infection / intracranial hemorrhage |","cm":1},{"n":"Psychogenic nonepileptic status |"}],"redflags":["تشنج > 5 دقیقه، نبود بازگشت هوشیاری، تب، علائم عصبی کانونی"],"guide":"IV، مانیتور قلبی و پالس‌اکسیمتری؛ ممکن اینتوباسیون؛ در صورت شل‌کننده، نوع کوتاه‌اثر تا فعالیت تشنجی قابل‌پایش یا EEG. شکل 145-1: 0 تا 5 دقیقه: حمایتی: IV، مانیتور، راه هوایی، اکسیژن، قند نقطه‌ای و گلوکز IV در صورت لزوم، محافظت بیمار. status مستقر (هدف 5 تا 10 دقیقه): lorazepam IV 2 mg تا 0.1 mg/kg یا diazepam IV 10 تا 20 mg (انتخاب اول lorazepam) سپس یکی از: fosphenytoin 20 PE/kg با 150 mg/min، phenytoin 20 mg/kg با 50 mg/min، levetiracetam 2000 تا 4000 mg IV؛ phenobarbital 20 mg/kg با 50 تا 75 mg/min. status مقاوم (هدف < 30 دقیقه): midazolam IV بار 0.2 mg/kg سپس انفوزیون 0.05 تا 2 mg/kg/h؛ propofol 1 mg/kg IV سپس 1 تا 10 mg/kg/h؛ ketamine 5 mg/kg/h؛ pentobarbital؛ اینتوباسیون، بستری ICU نورولوژی و EEG پیوسته. مشاوره زودهنگام نورولوژی.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 145: Seizures and Status Epilepticus in Adults, pp. 792–795"},"eclamptic-seizure-adult":{"id":"eclamptic-seizure-adult","variants":[{"id":"eclampsia-seizure-main","o":{"I":[{"t":"Obstetric ultrasound / fetal monitoring; head CT if focal deficit / atypical"}],"L":[{"t":"CBC with platelets, liver enzymes, creatinine, uric acid, urinalysis (proteinuria), glucose; type and screen"}],"S":[{"t":"Magnesium sulfate IV (loading and maintenance per obstetric protocol)","fl":[{"k":"hi","v":""},{"k":"ci","v":"monitor reflexes / respiratory rate / urine output; renal impairment"}]},{"t":"IV antihypertensive for severe hypertension (labetalol or hydralazine per obstetric protocol)"}],"T":[{"t":"Protect airway and from injury; left lateral decubitus; fetal monitoring"}],"Co":[{"t":"Obstetrics (early / emergent consult; delivery planning); ICU"}]},"name":"Eclamptic seizure","level":"I","imp":"Eclampsia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"زن ۲۵ ساله در هفته 36 با تشنج منتشر، فشار 170/110 و ادم.","why":"منیزیم سولفات IV و مشاوره زنان فوری."}],"ch":"145","name":"Eclamptic seizure (pregnancy / postpartum)","name_fa":"تشنج اکلامپتیک","cc":["seizure","pregnancy"],"keywords":"eclampsia, magnesium sulfate, postpartum seizure, preeclampsia, اکلامپسی, منیزیم سولفات","status":"draft","features":["اختلال زنان باردار از هفته 20 تا 8 هفته پس از زایمان: تشنج منتشر، هیپرتانسیون، ادم و پروتئینوری"],"ddx":[{"n":"Intracranial hemorrhage / PRES / CVT |","cm":1},{"n":"Epilepsy / hypoglycemia / toxic seizure |"}],"redflags":["فشار بالا، تشنج در بارداری یا پس از زایمان"],"guide":"magnesium sulfate IV به مشکوک اکلامپسی؛ مشاوره زودهنگام زنان؛ جزئیات فصل 61 (پره‌اکلامپسی/اکلامپسی).","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 145: Seizures and Status Epilepticus in Adults, pp. 792–795"},"guillain-barre-syndrome":{"id":"guillain-barre-syndrome","variants":[{"id":"gbs-main","o":{"I":[{"t":"CXR PA (respiratory status / aspiration); MRI spine to exclude cord compression if atypical"}],"L":[{"t":"Lumbar puncture (CSF: high protein, normal cell count); electrolytes (K, Mg, phosphate), CBC, creatinine, CK; forced vital capacity / negative inspiratory force; ECG"}],"S":[{"t":"IV immunoglobulin or plasmapheresis (neurology) — may shorten time to recovery","fl":[{"k":"ci","v":"IVIG — renal impairment / IgA deficiency"}]}],"T":[{"t":"Respiratory support as disease progresses (intubation if FVC < 20 mL/kg / NIF worsening); continuous cardiac monitoring (autonomic instability); DVT prophylaxis; supportive care"}],"Co":[{"t":"Neurology; admit monitored / ICU"}]},"name":"Guillain–Barré syndrome","level":"I","imp":"Guillain–Barré syndrome","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۴۰ ساله 2 هفته پس از اسهال با ضعف صعودی پاها، arefleksia و تنگی نفس خفیف.","why":"پایش تنفسی (FVC/NIF)، IVIG/plasmapheresis و بستری."}],"ch":"146","name":"Guillain–Barré syndrome (GBS)","name_fa":"سندرم گیلن‌باره","cc":["weakness","focal-neuro"],"keywords":"Guillain-Barre, GBS, ascending paralysis, areflexia, IVIG, plasmapheresis, cytoalbuminologic dissociation, گیلن باره, فلج صعودی","status":"draft","features":["پلی‌نوروپاتی حاد ایمن: تخریب میلین یا آکسون اعصاب محیطی؛ همراه عفونت ویروسی/تب، Campylobacter jejuni یا واکسیناسیون","تیپیک: ضعف یا فلج صعودی متقارن و از دست رفتن رفلکس تاندونی؛ نارسایی تنفسی و نوسان اتونوم؛ CSF: پروتئین بالا و WBC طبیعی","جدول 146-1 مرکزی در برابر محیطی؛ جدول 146-2 معیارها: لازم: ضعف پیشرونده بیش از یک اندام و arefleksia؛ حمایت‌کننده: پیشرفت روزها تا هفته‌ها، بهبود 2 تا 4 هفته پس از توقف پیشرفت، تقارن نسبی، علائم حسی خفیف، درگیری عصب کرانیال (Bell، دیسفاژی، دیزآرتری، افتالموپلژی)، اختلال اتونوم (تاکی/برادی‌کاردی، دیسریتمی، نوسان فشار، هیپوتانسیون وضعیتی، احتباس ادرار، یبوست، flushing، آنهیدروز، هیپرسالیواسیون)، نبود تب در شروع، dissociation سیتوآلبومینیک، EMG/NCS تیپیک"],"ddx":[{"n":"Spinal cord compression / transverse myelitis |","cm":1},{"n":"Myasthenia gravis / botulism / tick paralysis |","cm":1},{"n":"Hypokalemic paralysis / acute myopathy |"}],"redflags":["نارسایی تنفسی (FVC پایین)، اختلال اتونوم، ضعف بولبار"],"guide":"درمان اولیه حمایتی (پشتیبانی تنفسی هنگام پیشرفت)؛ مشاوره نورولوژی برای بستری مانیتورشده؛ IV immunoglobulin و plasmapheresis ممکن است زمان بهبود را کوتاه کنند.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 146: Acute Peripheral Neurologic Lesions, pp. 796–799"},"bell-palsy":{"id":"bell-palsy","variants":[{"id":"bell-palsy-main","o":{"I":[{"t":"(CT / MRI brain only if forehead strength preserved / other focal signs)"}],"L":[{"t":"(glucose; Lyme serology / HIV per risk and region)"}],"S":[{"t":"Prednisone 1 mg/kg/day PO for 7 days","fl":[{"k":"ci","v":"diabetes — monitor glucose; peptic ulcer"}]}],"T":[{"t":"Ophthalmic moisturizing ointment at night (and artificial tears; tape eye closed) to prevent corneal drying"},{"t":"Inspect ear canal for vesicles (Ramsay Hunt)"}],"Co":[{"t":"Follow-up with primary care or ENT; ophthalmology if eye symptoms"}]},"name":"Bell's palsy","level":"III","imp":"Bell's palsy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۳۵ ساله با افتادگی یک‌طرفه صورت از صبح، ناتوانی در بستن چشم و حرکت پیشانی ضعیف.","why":"پردنیزون 7 روز و حفاظت چشم؛ رد سکته."},{"id":"ramsay-hunt-facial","o":{"S":[{"t":"Famciclovir 500 mg PO three times daily for 7 days, or valacyclovir 1 g PO three times daily for 7 days","fl":[{"k":"ci","v":"dose adjust in renal impairment"}]},{"t":"Prednisone 1 mg/kg/day PO for 7 days"}],"T":[{"t":"Ophthalmic moisturizing ointment at night; analgesia"}],"Co":[{"t":"ENT follow-up"}]},"name":"Ramsay Hunt syndrome with facial palsy","level":"III","imp":"Ramsay Hunt syndrome","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"مرد ۶۰ ساله با فلج صورت، درد گوش و وزیکول در مجرای گوش خارجی.","why":"ضدویروس + پردنیزون."}],"ch":"146","name":"Bell's palsy and Ramsay Hunt syndrome","name_fa":"فلج بل و سندرم Ramsay Hunt","cc":["focal-neuro","ent"],"keywords":"Bell palsy, facial nerve palsy, prednisone, Ramsay Hunt, famciclovir, valacyclovir, eye protection, فلج بل, فلج صورت","status":"draft","features":["اختلال عصب کرانیال هفتم: ضعف یک‌طرفه صورت (از جمله پیشانی)، مشکل تکلم، ناتوانی در بستن چشم، ریزش غذا از یک سمت دهان؛ بدون یافته کانونی دیگر","افتراق: سکته، Lyme، GBS، تومور پاروتید، ضایعه گوش میانی، تومور زاویه پونتوسربلار، ضایعات عصب هشتم، HIV و بیماری عروقی؛ گوش را برای زخم ناشی از zoster بررسی کن (Ramsay Hunt)؛ حفظ قدرت پیشانی بل را بعید و ضایعه مرکزی ممکن (تصویربرداری مغز)"],"ddx":[{"n":"Stroke (forehead spared) |","cm":1},{"n":"Lyme disease / HIV / GBS / otitis media / tumor |"},{"n":"Ramsay Hunt syndrome |"}],"redflags":["حفظ قدرت پیشانی (مرکزی)، سایر یافته‌های کانونی، وزیکول گوش"],"guide":"کورتیکواستروئید سیستمیک شانس بهبود کامل را افزایش می‌دهد: prednisone 1 mg/kg/روز PO به مدت 7 روز. ضدویروس بدون فایده اثبات‌شده مگر Ramsay Hunt: famciclovir 500 mg PO سه بار روزانه × 7 روز یا valacyclovir 1 g PO سه بار روزانه × 7 روز. پماد مرطوب‌کننده چشم شب برای جلوگیری از خشکی قرنیه. پیگیری PCP یا ENT.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 146: Acute Peripheral Neurologic Lesions, pp. 796–799"},"focal-mononeuropathy-plexopathy":{"id":"focal-mononeuropathy-plexopathy","variants":[{"id":"mononeuropathy-main","o":{"L":[{"t":"(glucose / TSH / HbA1c as underlying cause screening)"}],"S":[{"t":"NSAID (anti-inflammatory)","fl":[{"k":"ci","v":"renal disease, peptic ulcer, anticoagulation"}]}],"T":[{"t":"Splint in neutral position (carpal tunnel) or appropriate splint for comfort; avoid provocative positions; treat underlying cause"}],"Co":[{"t":"Outpatient follow-up (EMG / nerve conduction studies; surgical referral if persistent / motor weakness)"}]},"name":"Focal mononeuropathy (carpal / cubital tunnel, peroneal, meralgia)","level":"III","imp":"Focal mononeuropathy","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۴۵ ساله با بی‌حسی و درد شبانه شست و انگشتان 2-3 دست راست، Phalen مثبت.","why":"آتل مچ خنثی و NSAID؛ پیگیری."},{"id":"plexopathy-main","o":{"I":[{"t":"Plain radiographs; MRI (plexus / spine); CT abdomen / pelvis for lumbosacral plexopathy (hemorrhage, aneurysm)"}],"L":[{"t":"CBC, glucose / HbA1c, ESR / CRP, electrolytes, coagulation"}],"T":[{"t":"Evaluation for acutely reversible causes (joint dislocation, traumatic injury); analgesia; sling / splint"}],"Co":[{"t":"Referral by cause (neoplasm: oncology / neurosurgery); neurology; vascular / surgery if aneurysm / retroperitoneal hemorrhage"}]},"name":"Plexopathy (brachial / lumbosacral)","level":"II","imp":"Plexopathy","cond":"Urgent","act":"CBR","diet":"NPO","ecg":"none","cxr":"PA","sc":"مرد ۵۵ ساله با ضعف پیشرونده بازوی چپ و درد شانه پس از پرتودرمانی سرطان ریه.","why":"علل قابل برگشت را رد کن؛ MRI و ارجاع."}],"ch":"146","name":"Focal mononeuropathies and plexopathies (carpal tunnel, cubital tunnel, peroneal, meralgia paresthetica)","name_fa":"مونونوروپاتی‌های کانونی و پلکسوپاتی‌ها","cc":["weakness","joint-limb-pain","focal-neuro"],"keywords":"carpal tunnel syndrome, cubital tunnel, foot drop, meralgia paresthetica, mononeuritis multiplex, brachial plexopathy, lumbosacral plexopathy, تونل کارپال, پلکسوپاتی","status":"draft","features":["مونونوروپاتی: اغلب فشار کانونی عصب؛ سیستمیک ممکن؛ carpal tunnel: فشار عصب median در مچ: درد، پارستزی و بی‌حسی در توزیع median؛ Tinel (ضربه سبک روی median ← شوک الکتریکی) و Phalen (فلکشن مچ 60 ثانیه ← تشدید)؛ cubital tunnel: عصب اولنار در آرنج: گزگز انگشت پنجم و نیمه خارجی چهارم؛ پیشرفت به فلج و آتروفی عضلات اینترینسیک دست؛ deep peroneal entrapment: foot drop و بی‌حسی بین انگشت اول و دوم؛ meralgia paresthetica: عصب لترال فمورال کوتانئوس: بی‌حسی و درد قدامی-خارجی ران؛ mononeuritis multiplex: چند عصب جدا از نظر زمان و آناتومی","پلکسوپاتی: تروما، جراحی، نئوپلاسم یا پرتودرمانی؛ بازوی پلکسوپاتی: ضعف بازو/شانه سپس درد و پارستزی؛ ED: علل قابل برگشت حاد (در رفتگی مفصل یا آسیب) و ارجاع (نئوپلاسم)؛ لومبوساکرال: کمتر ضربه؛ پرتو، آمیوتروفی دیابتی، آنوریسم آئورت، خونریزی رتروپریتوان، AVM؛ ضعف، کاهش حس، کاهش رفلکس؛ رادیوگرافی، MRI و CT شکم"],"ddx":[{"n":"Cervical / lumbar radiculopathy |","cm":1},{"n":"Stroke / spinal cord lesion |","cm":1},{"n":"Diabetic neuropathy / vasculitis / compartment syndrome |"}],"redflags":["ضعف پیشرونده، آتروفی، نقص عروقی، شک نئوپلاسم، خونریزی رتروپریتوان"],"guide":"درمان محافظه‌کارانه: ضدالتهاب؛ آتل برای راحتی؛ carpal tunnel: مچ در وضعیت خنثی؛ درمان علت زمینه‌ای نوروپاتی.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 146: Acute Peripheral Neurologic Lesions, pp. 796–799"},"botulism-neuromuscular":{"id":"botulism-neuromuscular","variants":[{"id":"botulism-main","o":{"I":[{"t":"CXR PA (respiratory status / aspiration)"}],"L":[{"t":"FVC / NIF; electrolytes, CBC; stool / serum toxin assay (public health); CSF if GBS in question"}],"S":[{"t":"Trivalent botulinum antitoxin 10 mL IV (infants: human botulism immunoglobulin)"}],"T":[{"t":"Respiratory support (intubation / ventilation as needed); NPO; wound debridement and antibiotics for wound botulism","fl":[{"k":"ci","v":"avoid aminoglycosides / magnesium (neuromuscular blockade)"}]}],"Co":[{"t":"Admit ICU; public health notification; infectious disease / toxicology"}]},"name":"Botulism","level":"I","imp":"Botulism","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۳۵ ساله پس از خوردن کنسرو خانگی با دوبینی، پتوز، دیزآرتری و ضعف نزولی.","why":"آنتی‌توکسین زود و پایش تنفسی؛ اطلاع به بهداشت."}],"ch":"146","name":"Botulism (foodborne, wound, infant)","name_fa":"بوتولیسم (غذایی، زخم، شیرخوار)","cc":["weakness","focal-neuro","dyspnea"],"keywords":"botulism, Clostridium botulinum, descending paralysis, antitoxin, infant botulism, BabyBIG, wound botulism, بوتولیسم","status":"draft","features":["اختلال اتصال عصبی-عضلانی ناشی از سم Clostridium botulinum؛ غذایی: کنسرو ناکافی؛ شیرخوار: اسپور خورده (اغلب عسل) و سم جذب سیستمیک؛ زخم: زخم یا سابقه تزریق IV","علائم 6 تا 48 ساعت پس از بلع؛ ممکن تهوع، استفراغ، اسهال قبلی؛ شکایت زودرس: چشم یا عضلات بولبار؛ ضعف متقارن نزولی؛ نارسایی تنفسی بالقوه"],"ddx":[{"n":"Guillain–Barré syndrome / myasthenia gravis |","cm":1},{"n":"Tick paralysis / stroke (brainstem) / diphtheria |"}],"redflags":["فلج نزولی، دیسفاژی/دیزآرتری، نارسایی تنفسی"],"guide":"حمایت تنفسی، trivalent botulinum antitoxin 10 mL IV و بستری؛ شیرخوار: human botulism immunoglobulin نیاز به تهویه مکانیکی و مدت ICU را کم می‌کند.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 146: Acute Peripheral Neurologic Lesions, pp. 796–799"},"als-complications":{"id":"als-complications","variants":[{"id":"als-acute-complication","o":{"I":[{"t":"CXR portable (aspiration pneumonia / atelectasis)"}],"L":[{"t":"Blood gas (may not reliably predict failure); FVC / NIF (FVC < 25 mL/kg or 50% decrease from predicted raises likelihood of pneumonia / respiratory failure); CBC, electrolytes, lactate, cultures"}],"S":[{"t":"Nebulizer treatments; steroids as indicated (optimize pulmonary function)"},{"t":"IV fluids as needed","fl":[{"k":"ci","v":"caution in heart failure"}]}],"A":[{"t":"Antibiotics for aspiration pneumonia (per community / aspiration regimen)"}],"T":[{"t":"Noninvasive ventilation or intubation as indicated; suction / cough assistance; NPO; aspiration precautions; honor goals-of-care / advance directives"}],"Co":[{"t":"Admit appropriate level of care (pneumonia, secretions, respiratory distress, ventilator need); neurology / palliative care; pulmonology"}]},"name":"Known ALS with respiratory failure / aspiration / choking","level":"I","imp":"ALS with respiratory failure / aspiration pneumonia","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate cautiously to SpO2 ≥ 92% (hypercapnia risk)","sc":"مرد ۶۰ ساله مبتلا به ALS با تنگی نفس، سرفه ضعیف، تب و ناتوانی در کنترل ترشحات.","why":"حمایت تنفسی (NIV/اینتوباسیون)، آنتی‌بیوتیک پنومونی و FVC."}],"ch":"147","name":"Amyotrophic lateral sclerosis (ALS) — respiratory and acute complications","name_fa":"اسکلروز جانبی آمیوتروفیک (ALS) — عوارض تنفسی و حاد","cc":["weakness","dyspnea","focal-neuro"],"keywords":"ALS, amyotrophic lateral sclerosis, motor neuron disease, aspiration pneumonia, forced vital capacity, noninvasive ventilation, ALS","status":"draft","features":["آتروفی و ضعف پیشرونده عضلانی؛ نورون حرکتی فوقانی: اسپاستیسیتی اندام، هایپررفلکسی، ناپایداری هیجانی؛ تحتانی: ضعف، آتروفی، فاسیکولاسیون، دیزآرتری، دیسفاژی، اشکال در جویدن؛ اوایل ممکن است نامتقارن","ضعف عضلات تنفسی ← تنگی نفس با فعالیت یا در استراحت؛ حس و شناخت اغلب سالم (تا 15% دمانس و Parkinsonism)","تشخیص زودرس دشوار (میانه تشخیص 14 ماه)؛ شک: علائم نورون حرکتی فوقانی و تحتانی بدون سایر اختلال CNS؛ افتراق: دیابت، اختلال تیروئید/پاراتیروئید، کمبود B12، فلزات سنگین، واسکولیت، تومور CNS"],"ddx":[{"n":"Respiratory failure / aspiration pneumonia (complications) |","cm":1},{"n":"B12 deficiency / thyroid disease / heavy metal / CNS tumor |"},{"n":"Cervical myelopathy / myasthenia gravis |"}],"redflags":["FVC < 25 mL/kg یا 50% کاهش، ناتوانی در کنترل ترشحات، پنومونی آسپیراسیون، دیسترس تنفسی"],"guide":"تشخیص جدید ALS در ED غیرمعمول؛ بیمار پایدار با علائم مشکوک: ارجاع به نورولوژیست اگر ورک‌آپ اولیه علت اورژانس نیافت. بیمار شناخته‌شده: نارسایی تنفسی، پنومونی آسپیراسیون، choking یا آسیب تروماتیک. بهینه‌سازی عملکرد ریه با نبولایزر، استروئید، آنتی‌بیوتیک و اینتوباسیون بر حسب اندیکاسیون؛ گاز خون پیش‌بینی نارسایی قابل‌اعتماد نیست؛ FVC < 25 mL/kg یا 50% کاهش از پیش‌بینی ← احتمال پنومونی و نارسایی تنفسی. پنومونی، ناتوانی در کنترل ترشحات، دیسترس تنفسی یا نیاز به ونتیلاتور: بستری سطح مناسب.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 147: Chronic Neurologic Disorders, pp. 800–805"},"myasthenia-crisis":{"id":"myasthenia-crisis","variants":[{"id":"myasthenic-crisis-main","o":{"I":[{"t":"CXR portable (infection / thymoma / aspiration)"}],"L":[{"t":"FVC / NIF; blood gas; CBC, electrolytes (K, Mg, Ca, phosphate), glucose, TSH, cultures (infection trigger); acetylcholine receptor antibodies (if undiagnosed)"}],"S":[{"t":"Edrophonium 1 mg IV slowly (diagnostic: myasthenic vs cholinergic crisis; improvement within minutes suggests myasthenic crisis) then neostigmine 0.5–2 mg IM / IV / SC (or 15 mg PO increments)","fl":[{"k":"ci","v":"edrophonium — bradycardia; have atropine ready"}]},{"t":"IV immunoglobulin or plasma exchange (neurology) for crisis; steroids (monitor — transient worsening possible)"}],"A":[{"t":"Antibiotics for infection triggers — avoid aminoglycosides, fluoroquinolones, macrolides, clindamycin (worsen weakness); use agents compatible with MG"}],"T":[{"t":"Respiratory support (noninvasive ventilation / intubation); when possible avoid depolarizing and nondepolarizing paralytic agents; check all ED drugs against Table 147-1 (avoid magnesium, β-blockers, lidocaine, phenytoin, opioids / sedatives where possible)"}],"Co":[{"t":"Neurology; ICU admission"}]},"name":"Myasthenic crisis / suspected respiratory failure","level":"I","imp":"Myasthenic crisis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","o2":"titrate to SpO2 ≥ 94%","sc":"زن ۴۰ ساله مبتلا به میاستنی با عفونت تنفسی، پتوز، دیسفاژی و تنگی نفس.","why":"FVC/NIF، پشتیبانی تنفسی، IVIG/plasma exchange؛ پرهیز از داروهای مضر."}],"ch":"147","name":"Myasthenia gravis and myasthenic crisis","name_fa":"میاستنی گراویس و بحران میاستنیک","cc":["weakness","dyspnea","eye"],"keywords":"myasthenia gravis, myasthenic crisis, cholinergic crisis, edrophonium, neostigmine, pyridostigmine, IVIG, plasma exchange, drugs to avoid, میاستنی گراویس","status":"draft","features":["اختلال خودایمن اتصال عصبی-عضلانی؛ ضعف و خستگی عضلانی؛ ضعف عضلات پروگزیمال اندام، اکستانسورهای گردن، صورت و بولبار؛ پتوز و دوبینی شایع؛ بدتر در طول روز و بهتر با استراحت؛ بحران میاستنیک: ضعف شدید عضلات تنفسی ← نارسایی تنفس","افتراق: Lambert-Eaton، بوتولیسم، اختلال تیروئید، سکته؛ تشخیص: edrophonium (مهارکننده استیل‌کولین‌استراز)، EMG، آنتی‌بادی گیرنده استیل‌کولین؛ edrophonium یا neostigmine باید ضعف را در اندام/چشم/حلق بهبود دهد","نارسایی تنفس: عفونت، جراحی اخیر، تغییر ایمونوساپرسانت؛ بحران میاستنیک ممکن در بیمار تشخیص‌داده‌نشده یا شناخته با تشدید یا درمان ناکافی"],"ddx":[{"n":"Cholinergic crisis (overmedication) |","cm":1},{"n":"Botulism / Guillain–Barré syndrome |","cm":1},{"n":"Lambert–Eaton / thyroid disease / stroke |"}],"redflags":["نارسایی تنفسی، دیسفاژی/آسپیراسیون، ضعف بولبار، عفونت یا داروی محرک"],"guide":"درمان: مهارکننده‌های استیل‌کولین‌استراز (pyridostigmine یا neostigmine)، تیمکتومی، سرکوب ایمنی (استروئید یا azathioprine)، تعدیل ایمنی (plasma exchange یا IVIG). بسیاری داروهای ED بر عملکرد عصبی-عضلانی اثر دارند: تداخل را بررسی کن (جدول 147-1: استروئید، ضدتشنج (phenytoin، منیزیم، باربیتورات، لیتیوم)، ضدمalaria (chloroquine، quinine)، محلول lactate، آنتی‌بیوتیک (آمینوگلیکوزید، فلوروکینولون، macrolide، clindamycin، tetracycline، sulfonamide، polymyxin، metronidazole)، روان‌گردان (chlorpromazine، droperidol، haloperidol)، قلبی (β-blocker، quinidine، procainamide، lidocaine، منیزیم، CCB)، بی‌حس‌کننده موضعی، اوپیوئید، thyroid، diphenhydramine، شل‌کننده، آرام‌بخش و مضعف تنفس، داروهای مسدودکننده عصبی-عضلانی). اینتوباسیون: در صورت امکان اجتناب از شل‌کننده‌های دپولاریزان و غیردپولاریزان. edrophonium 1 mg IV آهسته: تمایز بحران میاستنیک (درمان ناکافی) از کولینرژیک (اغلب overmedication)؛ رفع ضعف طی چند دقیقه ← تشدید میاستنی ← neostigmine 0.5 تا 2 mg IM/IV/SC یا افزایش‌های 15 mg PO.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 147: Chronic Neurologic Disorders, pp. 800–805"},"multiple-sclerosis-exacerbation":{"id":"multiple-sclerosis-exacerbation","variants":[{"id":"ms-exacerbation-main","o":{"I":[{"t":"MRI brain / cervical / thoracic spine with gadolinium (new lesions; exclude cord compression)"}],"L":[{"t":"Urinalysis and culture (postvoid residual > 100 mL); CBC, BMP, glucose (before steroids); ESR / CRP; consider Lyme / syphilis / HIV if atypical"}],"S":[{"t":"Methylprednisolone 500–1000 mg IV daily (high-dose; shortens exacerbation)","fl":[{"k":"ci","v":"uncontrolled infection; diabetes — monitor glucose"}]}],"T":[{"t":"Fever reduction (reduces temperature-related weakness); bladder scan / catheterization if retention; fall precautions"}],"Co":[{"t":"Neurology (consult); admit significant exacerbation requiring IV steroids / antibiotics"}]},"name":"MS exacerbation (relapse)","level":"II","imp":"Multiple sclerosis exacerbation","cond":"Urgent","act":"CBR","diet":"PO","ecg":"once","cxr":"none","sc":"زن ۳۲ ساله مبتلا به MS با ضعف پای راست، بی‌حسی و تاری دید یک‌چشمی طی 3 روز.","why":"عفونت را رد و استروئید دوز بالا با مشورت نورولوژی."}],"ch":"147","name":"Multiple sclerosis exacerbation","name_fa":"عود (exacerbation) مولتیپل اسکلروزیس","cc":["focal-neuro","eye","weakness"],"keywords":"multiple sclerosis, MS relapse, optic neuritis, Lhermitte sign, internuclear ophthalmoplegia, methylprednisolone, مولتیپل اسکلروزیس, MS","status":"draft","features":["دمیلیناسیون چندکانونی CNS: اختلال حرکتی، حسی، بینایی و/یا مخچه‌ای؛ انواع: relapsing-remitting (90%)، relapsing-progressive، progressive مزمن","Lhermitte: شوک الکتریکی/لرزش/درد از پشت به بازو/پا با خم کردن گردن؛ معاینه: کاهش قدرت، افزایش تون، هایپررفلکسی، clonus، کاهش حس ارتعاش و proprioception، Babinski مثبت، کاهش حس درد/دما؛ optic neuritis با از دست رفتن بینایی مرکزی (30% شروع): نقص مردمکی آوران (Marcus–Gunn)؛ internuclear ophthalmoplegia دوطرفه: ادداکشن غیرطبیعی و نیستاگموس افقی ← قویاً MS؛ مشکلات شناختی/هیجانی","شک: دو یا چند دوره طولانی اختلال عصبی با آسیب ماده سفید در بیش از یک محل؛ MRI: ضایعات متعدد supratentorial ماده سفید، حاشیه همگن اطراف بطن‌ها، ضایعات infratentorial یا نخاع؛ CSF: پروتئین و γ-globulin بالا؛ افتراق: SLE، Lyme، نوروسیفیلیس، HIV و GBS"],"ddx":[{"n":"Stroke / spinal cord compression / transverse myelitis |","cm":1},{"n":"Infection (UTI — pseudo-exacerbation) / Lyme / SLE / neurosyphilis / HIV |"}],"redflags":["از دست رفتن بینایی، ضعف پیشرونده، احتباس ادرار، تب، عفونت"],"guide":"مشاوره نورولوژی برای MS با شک تشدید؛ علائم جدید مشکوک: ارجاع نورولوژی. methylprednisolone با دوز بالا 500 تا 1000 mg روزانه مدت تشدید را کوتاه می‌کند. آزمایش UTI در بیمار با اختلال مثانه و باقیمانده پس از ادرار > 100 mL. منبع عفونت در تب؛ کاهش تب ضعف عضلانی وابسته به دما را کم می‌کند. بستری در تشدید قابل‌توجه با نیاز به استروئید یا آنتی‌بیوتیک IV.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 147: Chronic Neurologic Disorders, pp. 800–805"},"lambert-eaton-parkinson-polio":{"id":"lambert-eaton-parkinson-polio","variants":[{"id":"parkinson-ed-visit","o":{"L":[{"t":"Glucose, BMP, CBC, urinalysis (infection precipitating); orthostatic vital signs; ECG"}],"S":[{"t":"(IV fluids if orthostatic / dehydrated)","fl":[{"k":"ci","v":"caution in heart failure"}]}],"T":[{"t":"Review medications (avoid dopamine antagonists: haloperidol, metoclopramide, prochlorperazine); \"drug holiday\" 1 week may be considered with neurologist for new motor / psychiatric disturbance or decreased drug efficacy"}],"Co":[{"t":"Neurology follow-up"}]},"name":"Parkinson's disease — medication-related or motor / psychiatric change","level":"III","imp":"Parkinson's disease, acute complication","cond":"Urgent","act":"CBR","diet":"PO","ecg":"stat","cxr":"none","sc":"مرد ۷۰ ساله پارکینسونی با توهم، دیسکینزی و هیپوتانسیون ارتواستاتیک پس از افزایش دوز دارو.","why":"بازنگری دارو؛ علل ثانویه (عفونت، متابولیک) و نورولوژی."},{"id":"lems-postpolio","o":{"I":[{"t":"CXR PA / CT chest (lung cancer screening in LEMS)"}],"L":[{"t":"Electrolytes, CBC, TSH, CK; voltage-gated calcium channel antibodies (outpatient); CSF + stool / throat swab culture if acute febrile flaccid paralysis from endemic area"}],"T":[{"t":"Supportive care: analgesics, anti-inflammatory medications; muscle training / daily exercise (postpolio); respiratory monitoring (acute polio / bulbar symptoms)"},{"t":"LEMS: 3,4-diaminopyridine and immunosuppressants per neurology; lamotrigine may improve quality of life in postpolio syndrome"}],"Co":[{"t":"Neurology for disposition and follow-up; admit / infection control if acute poliomyelitis suspected"}]},"name":"Lambert–Eaton syndrome / postpolio syndrome / acute poliomyelitis (supportive)","level":"III","imp":"Lambert–Eaton / postpolio syndrome / poliomyelitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"PA","sc":"مرد ۶۵ ساله سیگاری با ضعف پروگزیمال پاها که با ورزش بهتر می‌شود؛ یا بیمار با پولیوی دوران کودکی و ضعف جدید و خستگی.","why":"حمایتی و ارجاع؛ جستجوی سرطان در LEMS."}],"ch":"147","name":"Lambert–Eaton syndrome, Parkinson's disease, poliomyelitis and postpolio syndrome","name_fa":"سندرم Lambert–Eaton، پارکینسون، فلج اطفال و سندرم پس از فلج اطفال","cc":["weakness","focal-neuro"],"keywords":"Lambert-Eaton, Parkinson disease, parkinsonism, drug-induced parkinsonism, poliomyelitis, postpolio syndrome, 3,4-diaminopyridine, پارکینسون, فلج اطفال","status":"draft","features":["Lambert–Eaton (LEMS): اختلال خودایمن؛ ضعف و خستگی نوسانی عضلات پروگزیمال اندام؛ کلاسیک: مردان سالمند با سرطان ریه؛ قدرت با ورزش مداوم/مکرر بهتر می‌شود (علامت Lambert)؛ میالژی، سفتی، پارستزی، طعم فلزی و علائم اتونوم؛ حرکات چشم سالم؛ EMG غیرطبیعی؛ آنتی‌بادی کانال کلسیم وابسته به ولتاژ","Parkinson: اختلال حرکتی اکستراپیرامیدال پیشرونده؛ چهار علامت: لرزش استراحت، cogwheel rigidity، برادی/آکینزی، اختلال وضعیت و تعادل؛ ابتدا لرزش «pill rolling» یک‌طرفه اندام فوقانی که با حرکت ارادی بهتر می‌شود؛ تشخیص بالینی؛ parkinsonism ثانویه: مواد مخدر، سموم، نورولپتیک، هیدروسفالی، ضربه سر؛ دارویی: معمولاً آکینزی","داروهای Parkinson (افزایش دوپامین، آنتی‌کولینرژیک، آگونیست دوپامین): عوارض: اختلال روانی/خواب، بی‌اشتهایی، تهوع، استفراغ، دیسریتمی، هیپوتانسیون ارتواستاتیک، دیسکینزی و دیستونی","پولیومیلیت: انتروویروس؛ اغلب بدون علامت یا بیماری ویروسی خفیف؛ 1 تا 2% بیماری عمده: ضعف و شلی نامتقارن پروگزیمال اندام، arefleksia، فاسیکولاسیون؛ حداکثر فلج ≤ 5 روز، آتروفی؛ بهبود تا 1 سال؛ در آمریکا ریشه‌کن (1979) ولی endemic در نیجریه، پاکستان، افغانستان و هند؛ postpolio syndrome: بازگشت علائم حرکتی پس از دهه‌ها: خستگی عضلانی، درد مفصل، ضعف عضلات جدید و قبلی، مشکلات بولبار/تنفسی/خواب","پولیو حاد: تب، منژیت آسپتیک و فلج شل نامتقارن با ریفلکس از دست رفته و حس سالم؛ CSF: پلئوسیتوز و کشت ویروس؛ سواب حلق/رکتوم؛ افتراق: GBS، نوروپاتی (mono، Lyme، پورفیری)، الکترولیت، سموم، میوپاتی، سایر ویروس‌ها"],"ddx":[{"n":"Guillain–Barré syndrome / myasthenia gravis |","cm":1},{"n":"Drug-induced parkinsonism (neuroleptics) / NPH |"},{"n":"Paraneoplastic syndromes (lung cancer) |"}],"redflags":["ضعف تنفسی/بولبار، فلج شل حاد پس از سفر به منطقه endemic"],"guide":"Lambert–Eaton: درمان عمدتاً حمایتی؛ 3,4-diaminopyridine انتقال عصبی-عضلانی را افزایش می‌دهد؛ ایمونوساپرسانت ممکن است شدت را کم کند. Parkinson: بیماران دارویی با اختلال حرکتی/روانی جدید یا کاهش اثر دارو: «drug holiday» یک‌هفته‌ای با مشورت نورولوژیست. پولیو: درمان حاد پس‌پولیو حمایتی با مسکن و ضدالتهاب؛ تمرین عضلانی و ورزش روزانه؛ lamotrigine ممکن کیفیت زندگی را بهتر کند؛ مشاوره نورولوژیست.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 147: Chronic Neurologic Disorders, pp. 800–805"},"meningitis-adult":{"id":"meningitis-adult","variants":[{"id":"meningitis-bacterial-suspected","o":{"I":[{"t":"CT head BEFORE LP if altered mental status, new seizure, immunocompromise, focal deficit, or papilledema (do not delay antibiotics); no LP if significant brain shift"},{"t":"CXR portable"}],"L":[{"t":"Lumbar puncture: opening pressure, cell count with differential, protein, glucose (with serum glucose), Gram stain and bacterial culture; consider HSV / enterovirus PCR, bacterial antigen, fungal studies in immunocompromised"},{"t":"Blood cultures ×2 (BEFORE antibiotics); CBC, glucose, electrolytes, BUN, creatinine, coagulation, lactate; HIV as indicated"}],"S":[{"t":"Dexamethasone 10 mg IV every 6 h for 4 days (0.15 mg/kg every 6 h in children ≥ 3 months) given before or with first antibiotic dose","fl":[{"k":"hi","v":""}]}],"A":[{"t":"Ceftriaxone 2 g IV plus vancomycin 15 mg/kg IV (adults < 50 years)","fl":[{"k":"hi","v":""}]},{"t":"Add ampicillin 2 g IV for Listeria risk (age ≥ 50, pregnancy, alcoholism, immunocompromised)"},{"t":"Start antibiotics immediately after blood cultures if CT / diagnostic delay; otherwise as soon as possible after prompt LP"}],"T":[{"t":"Droplet isolation until meningococcus excluded; neuro checks; seizure precautions; antipyretic / analgesia"}],"Co":[{"t":"Admit ICU / monitored (IV antibiotics); infectious disease; public health / prophylaxis of close contacts if meningococcal"}]},"name":"Suspected bacterial meningitis (empiric antibiotics + LP)","level":"I","imp":"Suspected bacterial meningitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۳۰ ساله با تب 39.5، سردرد شدید، سفتی گردن و گیجی از 12 ساعت قبل.","why":"کشت خون، آنتی‌بیوتیک و دگزامتازون فوراً؛ LP یا CT."},{"id":"meningitis-aseptic-viral","o":{"L":[{"t":"Lumbar puncture (cell count, protein, glucose, Gram stain, culture; enterovirus / HSV PCR); CBC, electrolytes"}],"S":[{"t":"IV / oral hydration ; antiemetic, analgesics","fl":[{"k":"ci","v":"caution in heart failure / CKD"}]}],"T":[{"t":"Supportive care; consider empiric antibiotics until bacterial meningitis excluded if CSF equivocal"}],"Co":[{"t":"Admit if bacterial meningitis not excluded; discharge with follow-up only if low-risk and CSF reliably viral"}]},"name":"Aseptic (viral) meningitis — supportive care","level":"III","imp":"Aseptic (viral) meningitis","cond":"Urgent","act":"CBR","diet":"PO","ecg":"none","cxr":"none","sc":"زن ۲۵ ساله در تابستان با تب، سردرد و سفتی خفیف گردن؛ CSF: WBC 150 لنفوسیتی، گلوکز و پروتئین نرمال، Gram منفی.","why":"حمایتی؛ باکتریال را رد کن."}],"ch":"148","name":"Meningitis in adults (bacterial and aseptic)","name_fa":"منژیت بزرگسال (باکتریال و آسپتیک)","cc":["headache","fever","altered-mental-status"],"keywords":"bacterial meningitis, aseptic meningitis, lumbar puncture, ceftriaxone, vancomycin, ampicillin, dexamethasone, Kernig, Brudzinski, nuchal rigidity, منژیت, پونکسیون کمری","status":"draft","features":["منژیت: التهاب پرده‌های مغز و نخاع؛ باکتریال (اغلب ارگانیسم کپسول‌دار): اورژانس تهدیدکننده حیات با مرگ‌ومیر و عوارض قابل‌توجه حتی با درمان به‌موقع؛ آسپتیک: علل غیرباکتریال (دارو، روماتولوژیک، قارچ، ویروس؛ انتروویروس و اکوویروس شایع‌ترین)","تریاد کلاسیک: تب، سفتی گردن و تغییر هوشیاری (کمتر از نیمی هر سه)؛ سردرد، تب، درد گردن، تهوع و استفراغ غیراختصاصی؛ دشواری در سنین خیلی پایین/بالا","معاینه: تب؛ علائم مننژیال: nuchal rigidity، Kernig (درد کمر و پا با فلکسیون هیپ و اکستانسیون زانو)، Brudzinski (فلکسیون هیپ با خم کردن غیرفعال گردن) ولی حساسیت پایین؛ وضعیت ذهنی و نقص عصبی (فلج کرانیال)؛ پتشی و splinter hemorrhage","LP فوری تشخیصی؛ CT قبل از LP در: تغییر هوشیاری، تشنج جدید، نقص ایمنی، علائم کانونی یا پاپیلادم (رد توده و herniation؛ شکل 148-1: LP نباید با جابه‌جایی مغز در CT انجام شود و درمان تجربی ادامه یابد)؛ CSF: cell count/diff، پروتئین، گلوکز، Gram و کشت؛ اضافی در نقص ایمنی یا شک اختصاصی: PCR HSV/انتروویروس، آنتی‌ژن باکتری، قارچ؛ سایر: CBC، قند/الکترولیت، BUN، کراتینین؛ کشت خون (به‌ویژه اگر آنتی‌بیوتیک قبل از LP)","جدول 148-1 CSF: باکتریال: فشار باز بالا، کدر؛ WBC > 1000–2000/mm³ با > 80% PMN؛ گلوکز < 40 (CSF/خون < 0.3–0.4)؛ پروتئین > 200؛ Gram مثبت (60 تا 80% قبل از آنتی‌بیوتیک، 7 تا 41% بعد)؛ ویروسی: فشار نرمال، شفاف یا خونی؛ WBC < 300 با لنفوسیت؛ گلوکز نرمال؛ پروتئین < 200؛ قارچی: WBC < 500؛ گلوکز نرمال تا کمی کم؛ پروتئین > 200؛ نئوپلاستیک: WBC < 300؛ سیتولوژی مثبت","افتراق: SAH، نئوپلاسم مننژ، آبسه مغز، توکسوپلاسموز مغزی و عفونت‌های سیستمیک"],"ddx":[{"n":"Subarachnoid hemorrhage |","cm":1},{"n":"Encephalitis (HSV) / brain abscess |","cm":1},{"n":"Meningeal neoplasm / cerebral toxoplasmosis / systemic infection |"}],"redflags":["تب + سفتی گردن + تغییر هوشیاری، پتشی (مننگوکوک)، نقص ایمنی، تشنج، علائم کانونی"],"guide":"شک بالا به منژیت باکتریال: شروع آنتی‌بیوتیک تجربی بر اساس عوامل خطر و پاتوژن‌های محتمل: به‌محض ممکن پس از LP سریع، یا فوراً پس از کشت خون اگر تصویربرداری/تست دیگر انجام می‌شود. < 50 سال: ceftriaxone 2 g IV + vancomycin 15 mg/kg IV؛ ریسک Listeria (≥ 50 سال، باردار، الکلی، نقص ایمنی): افزودن ampicillin 2 g IV. dexamethasone 10 mg IV هر 6 ساعت × 4 روز بزرگسال (0.15 mg/kg هر 6 ساعت × 4 روز کودک ≥ 3 ماه) همزمان یا قبل از اولین دوز آنتی‌بیوتیک ممکن مرگ‌ومیر و عوارض را در برخی زیرگروه‌ها کم کند. بستری برای آنتی‌بیوتیک IV و مراقبت.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 148: Central Nervous System and Spinal Infections, pp. 806–812"},"encephalitis-hsv":{"id":"encephalitis-hsv","variants":[{"id":"encephalitis-main","o":{"I":[{"t":"CT head before LP (AMS / seizure); MRI brain (medial temporal / inferior frontal lobes — HSV)"}],"L":[{"t":"Lumbar puncture with HSV / VZV / enterovirus PCR; cell count, protein, glucose, Gram stain / culture; CBC, electrolytes, glucose, creatinine (acyclovir dosing), blood cultures; HIV"}],"S":[{"t":"Acyclovir 10 mg/kg IV every 8 h","fl":[{"k":"hi","v":""},{"k":"ci","v":"renal impairment — adjust dose; ensure hydration"}]},{"t":"Cytomegalovirus encephalitis: ganciclovir 5 mg/kg IV","fl":[{"k":"ci","v":"neutropenia / renal impairment"}]},{"t":"Antiepileptic therapy for seizures; empiric antibacterial meningitis coverage until bacterial excluded"}],"T":[{"t":"Seizure precautions; supportive care; neuro checks"}],"Co":[{"t":"Admit ICU / monitored; neurology; infectious disease"}]},"name":"Suspected viral encephalitis (HSV)","level":"I","imp":"Suspected viral encephalitis","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"none","sc":"زن ۴۰ ساله با تب، گیجی، تغییر رفتار و تشنج؛ MRI: ضایعه تمپورال.","why":"acyclovir فوری و LP؛ بدون انتظار PCR."}],"ch":"148","name":"Encephalitis (HSV and other viral)","name_fa":"انسفالیت (HSV و سایر ویروسی)","cc":["altered-mental-status","fever","seizure","headache"],"keywords":"encephalitis, HSV encephalitis, acyclovir, ganciclovir, CMV encephalitis, temporal lobe, انسفالیت, آسیکلوویر","status":"draft","features":["عفونت پارانشیم مغز با التهاب CNS؛ اغلب ویروسی؛ HSV قابل‌درمان‌ترین علت؛ تب، سفتی گردن، سردرد مثل منژیت باکتریال + تغییر هوشیاری، نقص شناختی، علائم روانی یا تشنج","LP: pleocytosis؛ HSV PCR؛ MRI: ضایعات لوب تمپورال داخلی و فرونتال تحتانی ← HSV (معمولاً بخشی از ED نیست)"],"ddx":[{"n":"Bacterial meningitis / brain abscess |","cm":1},{"n":"Autoimmune encephalitis / toxic-metabolic encephalopathy |"}],"redflags":["تشنج، تغییر شخصیت، تب، علائم کانونی"],"guide":"acyclovir 10 mg/kg IV برای پوشش HSV یا zoster؛ CMV: ganciclovir 5 mg/kg IV؛ سایر انسفالیت‌های ویروسی بدون درمان ضدمیکروبی مؤثر: حمایتی. بستری برای درمان IV.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 148: Central Nervous System and Spinal Infections, pp. 806–812"},"brain-abscess":{"id":"brain-abscess","variants":[{"id":"brain-abscess-main","o":{"I":[{"t":"CT head with contrast (ring-enhancing lesion; thin ring around low-density center) or MRI with gadolinium; CT noncontrast first if unstable"},{"t":"CXR portable; sinus / mastoid imaging for source"}],"L":[{"t":"Blood cultures ×2 (before antibiotics); CBC, ESR / CRP, electrolytes, glucose, creatinine, coagulation; HIV; cultures of other infected sites","fl":[{"k":"ci","v":"avoid lumbar puncture when abscess / mass lesion suspected or identified"}]}],"A":[{"t":"Otogenic: cefotaxime 2 g IV every 4–6 h or ceftriaxone 2 g IV every 12 h PLUS metronidazole 500 mg IV every 8 h"},{"t":"Sinogenic: cefotaxime 2 g IV every 6 h or ceftriaxone 2 g IV every 12 h PLUS metronidazole 500 mg IV every 8 h"},{"t":"Odontogenic: penicillin G 4 million units IV every 4 h (alt: ceftriaxone 2 g every 12 h PLUS metronidazole 500 mg every 6 h)"},{"t":"Penetrating trauma: cefotaxime 2 g IV every 6 h or ceftriaxone 2 g every 12 h PLUS metronidazole 500 mg every 8 h ± rifampin 10 mg/kg every 24 h"},{"t":"After neurosurgical procedure: vancomycin 25–30 mg/kg IV load (or linezolid 600 mg IV every 12 h) PLUS ceftazidime 2 g IV every 8 h ± rifampin 10 mg/kg every 24 h (substitutions: meropenem 2 g every 8 h, piperacillin/tazobactam 4.5 g every 6 h, or cefepime 2 g every 8 h for ceftazidime)"},{"t":"Unknown source: cefotaxime 2 g IV every 6 h PLUS metronidazole 500 mg IV every 6 h","fl":[{"k":"hi","v":""}]}],"T":[{"t":"Seizure precautions; antiepileptic if seizures; ICP management if raised (head elevation)"}],"Co":[{"t":"Neurosurgery (admission; surgery for diagnosis, pathogen identification, definitive treatment); infectious disease; ENT / dental source control"}]},"name":"Brain abscess (empiric antibiotics by source)","level":"I","imp":"Brain abscess","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"portable","sc":"مرد ۴۵ ساله با اوتیت مزمن، تب، سردرد 10 روزه و همی‌پارزی خفیف؛ CT با کنتراست: ضایعه حلقه‌ای.","why":"آنتی‌بیوتیک بر اساس منبع و مشاوره نوروسرجری؛ بدون LP."}],"ch":"148","name":"Brain abscess","name_fa":"آبسه مغز","cc":["headache","fever","focal-neuro","altered-mental-status"],"keywords":"brain abscess, ring-enhancing lesion, otogenic, sinogenic, odontogenic, metronidazole, ceftriaxone, آبسه مغز","status":"draft","features":["عفونت باکتریال پارانشیم مغز؛ حفره چرکی مرکزی با گرانولاسیون و کپسول فیبروز؛ علائم غیراختصاصی: سردرد، سفتی گردن، تب، استفراغ، گیجی یا تغییر هوشیاری؛ علائم منبع (درد گوش یا سینوس)؛ 1 تا 8 هفته قبل از تشخیص","تصویربرداری لازم: CT بدون کنتراست (ادم اطراف)، CT با کنتراست (حلقه نازک enhancement دور مرکز کم‌دانسیته)، MRI حساس؛ از LP در شک یا وجود آبسه/توده اجتناب؛ کشت خون/سایر محل‌ها"],"ddx":[{"n":"Meningitis / encephalitis |","cm":1},{"n":"Brain neoplasm / cerebrovascular disease / subacute hemorrhage / toxoplasmosis |"}],"redflags":["تب + سردرد + علائم کانونی، منبع گوش/سینوس/دندان، ICP بالا"],"guide":"آنتی‌بیوتیک تجربی زودهنگام بر اساس منبع محتمل (جدول 148-2): otogenic: cefotaxime 2 g IV هر 4 تا 6 ساعت یا ceftriaxone 2 g IV هر 12 ساعت + metronidazole 500 mg IV هر 8 ساعت؛ odontogenic: penicillin G 4 میلیون واحد IV هر 4 ساعت (جایگزین: ceftriaxone 2 g هر 12 ساعت + metronidazole 500 mg هر 6 ساعت)؛ sinogenic: cefotaxime 2 g IV هر 6 ساعت یا ceftriaxone 2 g هر 12 ساعت + metronidazole 500 mg هر 8 ساعت؛ تروما نافذ: cefotaxime 2 g هر 6 ساعت یا ceftriaxone 2 g هر 12 ساعت + metronidazole 500 mg هر 8 ساعت ± rifampin 10 mg/kg/24 ساعت؛ پس از جراحی مغز: vancomycin بار 25 تا 30 mg/kg IV یا linezolid 600 mg IV هر 12 ساعت + ceftazidime 2 g IV هر 8 ساعت ± rifampin (جایگزین: meropenem 2 g هر 8 ساعت یا piperacillin/tazobactam 4.5 g هر 6 ساعت یا cefepime 2 g هر 8 ساعت به جای ceftazidime)؛ منبع نامعلوم: cefotaxime 2 g IV هر 6 ساعت + metronidazole 500 mg IV هر 6 ساعت. مشاوره نوروسرجری و بستری (بسیاری نیاز به جراحی برای تشخیص، شناسایی پاتوژن و درمان قطعی).","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 148: Central Nervous System and Spinal Infections, pp. 806–812"},"spinal-epidural-abscess":{"id":"spinal-epidural-abscess","variants":[{"id":"spinal-epidural-abscess-main","o":{"I":[{"t":"MRI spine (whole spine) with gadolinium (preferred); CT with myelography if MRI not possible"},{"t":"CXR PA (source: endocarditis / pneumonia)"}],"L":[{"t":"CBC, ESR, CRP; blood cultures ×2 (positive in ~40%; draw before antibiotics); BMP, glucose, creatinine, coagulation; urinalysis; HIV; postvoid residual"}],"A":[{"t":"Vancomycin 25–30 mg/kg IV PLUS ceftazidime 2 g IV or cefepime 2 g IV (start in ED if neurologic dysfunction, sepsis or systemic illness, or surgery not immediately available)","fl":[{"k":"hi","v":""}]},{"t":"Add gentamicin 5 mg/kg IV if recent neurosurgical procedure","fl":[{"k":"ci","v":"renal impairment"}]}],"T":[{"t":"Neurologic checks (motor, sensory, rectal tone, perineal sensation, bladder); bed rest / spine precautions; analgesia"}],"Co":[{"t":"Emergent spine surgery consultation (surgical debridement common); admit for IV antibiotics and close monitoring; infectious disease"}]},"name":"Spinal epidural abscess","level":"I","imp":"Spinal epidural abscess","cond":"Emergent","act":"CBR","diet":"NPO","ecg":"stat","cxr":"PA","sc":"مرد ۵۰ ساله مصرف‌کننده تزریقی با تب، درد شدید کمر، حساسیت midline و ضعف خفیف پاها.","why":"MRI با گادولینیوم و مشاوره جراحی؛ آنتی‌بیوتیک در نقص عصبی."}],"ch":"148","name":"Spinal epidural abscess","name_fa":"آبسه اپیدورال ستون فقرات","cc":["back-neck-pain","fever","focal-neuro"],"keywords":"spinal epidural abscess, vertebral osteomyelitis, back pain fever, MRI gadolinium, vancomycin, ceftazidime, cauda equina, آبسه اپیدورال","status":"draft","features":["عفونت نادر: تجمع ماده چرکی در فضای اپیدورال؛ تا نیمی از انتشار هماتوژن از بافت نرم، ادرار یا تنفس؛ بیشتر توراسیک و لومبار","تریاد کلاسیک (درد پشت، تب، علائم عصبی) در اقلیت؛ درد پشت 70 تا 90% و تب شایع؛ چهار مرحله: (1) درد پشت، تب، حساسیت موضعی ستون؛ (2) تحریک ستون با درد رادیکولر، هایپررفلکسی و سفتی گردن؛ (3) بی‌اختیاری مدفوع/ادرار + نقص عصبی کانونی؛ (4) فلج حرکتی اندام تحتانی","عوامل خطر: نقص ایمنی، تزریق IV مواد، جراحی ستون، پروسیجر اخیر (LP، بی‌حسی اپیدورال)؛ معاینه: حساسیت یا پرکاشن midline ستون؛ cauda equina: کاهش تون رکتال (حساسیت 60 تا 80%)، کاهش حس پرینه (75%)","تشخیص اغلب دیررس؛ CBC، ESR، CRP؛ کشت خون در 40% مثبت؛ MRI با gadolinium ارجح؛ CT myelography اگر MRI ممکن نیست"],"ddx":[{"n":"Cauda equina syndrome / disc herniation / spinal cord compression (tumor) |","cm":1},{"n":"Vertebral osteomyelitis / discitis / pyelonephritis |"},{"n":"Transverse myelitis / GBS |"}],"redflags":["تب + درد پشت، نقص عصبی، احتباس ادرار، IVDU، پروسیجر ستون اخیر"],"guide":"مشاوره اورژانس با جراح ستون؛ داده قطعی عمل در برابر آنتی‌بیوتیک تنها نیست ولی بسیاری دبریدمان جراحی می‌شوند. آنتی‌بیوتیک تجربی اگر نقص عصبی، علائم سپسیس یا جراحی فوری در دسترس نیست: vancomycin 25 تا 30 mg/kg IV + ceftazidime 2 g IV یا cefepime 2 g IV؛ در پروسیجر نوروسرجری اخیر: gentamicin 5 mg/kg IV اضافی. بستری برای آنتی‌بیوتیک IV، پایش، چک عصبی و احتمال دبریدمان.","section":"neurology","source":"Tintinalli's Emergency Medicine Manual, 8th ed., Ch. 148: Central Nervous System and Spinal Infections, pp. 806–812"}});
